:root {
  font-family: "Roboto", sans-serif;
  color: #f1f5fa;
  background: #09090b;
  font-synthesis: none;
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  font-optical-sizing: auto;
  font-weight: 400;
  --page: #09090b;
  --surface: #121214;
  --surface-raised: #1b1b1e;
  --text: #f1f5fa;
  --muted: #929eac;
  --line: rgba(255, 255, 255, .1);
  --brand-accent-hue: 355;
  --brand-accent: hsl(var(--brand-accent-hue) 60% 60%);
  --brand-accent-dark: hsl(var(--brand-accent-hue) 73% 26%);
  --brand-accent-deep: hsl(var(--brand-accent-hue) 83% 41%);
  --brand-accent-vivid: hsl(var(--brand-accent-hue) 97% 44%);
  --brand-accent-hover: hsl(var(--brand-accent-hue) 100% 39%);
  --brand-accent-hover-strong: hsl(var(--brand-accent-hue) 98% 36%);
  --brand-accent-hover-soft: hsl(var(--brand-accent-hue) 80% 71%);
  --brand-accent-focus: hsl(var(--brand-accent-hue) 100% 64%);
  --brand-accent-surface: hsl(var(--brand-accent-hue) 20% 8%);
  --brand-accent-surface-hover: hsl(var(--brand-accent-hue) 40% 11%);
  --accent: var(--brand-accent);
  --accent-secondary: var(--brand-accent-dark);
  --accent-ink: #fff;
}

* {
  box-sizing: border-box;
}

html {
  min-width: 320px;
  scroll-behavior: smooth;
  scroll-padding-top: 90px;
}

body {
  min-width: 320px;
  margin: 0;
  background: var(--page);
}

body,
button,
input,
select,
textarea {
  font-family: "Roboto", sans-serif;
}

button,
a,
input,
textarea {
  -webkit-tap-highlight-color: transparent;
}

button,
a {
  color: inherit;
}

a {
  text-decoration: none;
}

button {
  font-size: inherit;
}

button:focus-visible,
a:focus-visible,
input:focus-visible,
textarea:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 3px;
}

.route-style-loading,
.route-style-error {
  display: grid;
  min-height: 100vh;
  place-content: center;
  gap: 16px;
  padding: 24px;
  color: var(--text);
  text-align: center;
}

.route-style-error button {
  justify-self: center;
  padding: 10px 16px;
  border: 1px solid var(--line);
  border-radius: 6px;
  background: var(--surface);
  color: var(--text);
  cursor: pointer;
}

.not-found-main {
  display: grid;
  min-height: 100vh;
  place-items: center;
  padding: 24px;
}

.not-found-page {
  display: grid;
  width: min(100%, 520px);
  justify-items: center;
  gap: 12px;
  padding: clamp(26px, 6vw, 48px);
  border: 1px solid var(--line);
  border-radius: 18px;
  background:
    radial-gradient(ellipse at 50% 0, color-mix(in srgb, var(--accent) 10%, transparent), transparent 58%),
    linear-gradient(145deg, var(--surface-raised), var(--surface) 72%);
  box-shadow: 0 24px 70px rgba(0, 0, 0, .34), inset 0 1px rgba(255, 255, 255, .045);
  text-align: center;
}

.not-found-mark {
  display: grid;
  width: 58px;
  height: 58px;
  place-items: center;
  border: 1px solid color-mix(in srgb, var(--accent) 28%, transparent);
  border-radius: 17px;
  background: color-mix(in srgb, var(--accent) 9%, transparent);
  color: var(--accent);
}

.not-found-mark svg {
  width: 30px;
  height: 30px;
  stroke: currentColor;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-width: 1.7;
}

.not-found-page .eyebrow {
  margin: 4px 0 0;
  color: var(--accent);
  font-size: 10px;
  font-weight: 750;
  letter-spacing: .16em;
}

.not-found-page h1 {
  margin: 0;
  color: var(--text);
  font-family: Manrope, sans-serif;
  font-size: clamp(24px, 5vw, 34px);
  font-weight: 650;
  letter-spacing: -.045em;
  line-height: 1.15;
}

.not-found-page > p:not(.eyebrow) {
  max-width: 360px;
  margin: 0;
  color: var(--muted);
  font-size: 13px;
  line-height: 1.65;
}

.not-found-actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 10px;
  margin-top: 8px;
}

@media (max-width: 480px) {
  .not-found-main {
    padding: 16px;
  }

  .not-found-actions {
    width: 100%;
    flex-direction: column;
  }

  .not-found-actions .button {
    width: 100%;
  }
}

#inventory,
#services,
#sell,
#sell-form,
#about,
#contact,
#location-title {
  scroll-margin-top: 112px;
}
.site-header {
  position: fixed;
  z-index: 20;
  top: 0;
  left: 0;
  display: flex;
  width: 100%;
  height: 94px;
  align-items: center;
  justify-content: space-between;
  padding: 0 7.3%;
  border-bottom: 1px solid rgba(220, 220, 220, .12);
  background: rgba(9, 9, 11, .88);
  box-shadow: 0 8px 28px rgba(0, 0, 0, .18);
  -webkit-backdrop-filter: blur(16px);
  backdrop-filter: blur(16px);
}

.brand {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  font-family: 'Arial Narrow', Manrope, sans-serif;
  font-size: 19px;
  font-weight: 800;
  letter-spacing: -.075em;
}

.brand-logo {
  display: block;
  width: 150px;
  height: auto;
}

.brand-light {
  color: #a7b3c1;
  font-weight: 500;
}

.brand-mark {
  display: flex;
  width: 22px;
  height: 22px;
  align-items: center;
  justify-content: center;
  gap: 2px;
  transform: skew(-17deg);
}

.brand-mark i {
  display: block;
  width: 4px;
  height: 15px;
  border-radius: 4px;
  background: #009246;
}

.brand-mark i:nth-child(2) {
  height: 21px;
  background: #f5f5f5;
}

.brand-mark i:nth-child(3) {
  height: 11px;
  background: #ce2b37;
}

.brand-main {
  gap: 10px;
  font-size: 25px;
}

.brand-main .brand-logo {
  width: 190px;
}

.brand-main .brand-mark {
  width: 27px;
  height: 27px;
  gap: 2px;
}

.brand-main .brand-mark i {
  width: 5px;
  height: 18px;
}

.brand-main .brand-mark i:nth-child(2) {
  height: 26px;
}

.brand-main .brand-mark i:nth-child(3) {
  height: 13px;
}

.header-actions {
  display: flex;
  align-items: center;
  gap: clamp(12px, 2.2vw, 27px);
}

.header-nav {
  display: flex;
  align-items: center;
  gap: clamp(18px, 2.5vw, 34px);
  margin-left: auto;
  margin-right: auto;
  padding: 0 36px;
}

.header-nav button {
  padding: 10px 0;
  border: 0;
  background: transparent;
  color: #b7c1cc;
  cursor: pointer;
  font-size: 12px;
  font-weight: 500;
  transition: color .2s ease;
}

.header-nav button:hover {
  color: var(--accent);
}

.italian-flag {
  display: inline-flex;
  width: 29px;
  height: 19px;
  overflow: hidden;
  border: 1px solid rgba(255, 255, 255, .45);
  border-radius: 2px;
  box-shadow: 0 3px 14px rgba(0, 0, 0, .24);
  transform: skew(-7deg);
}

.italian-flag i {
  flex: 1;
}

.italian-flag i:nth-child(1) {
  background: #009246;
}

.italian-flag i:nth-child(2) {
  background: #f4f5f0;
}

.italian-flag i:nth-child(3) {
  background: #ce2b37;
}

.cart-toggle {
  position: relative;
  display: inline-flex;
  min-height: 42px;
  align-items: center;
  gap: 16px;
  padding: 0 11px;
  border: 1px solid var(--line);
  background: rgba(26, 26, 28, .55);
  color: var(--text);
  cursor: pointer;
  transition: border-color .2s ease, background .2s ease;
}

.admin-header-link {
  min-height: 42px;
  padding: 0 14px;
  border: 1px solid rgba(206, 43, 55, .55);
  background: rgba(206, 43, 55, .09);
  color: #ffb0aa;
  cursor: pointer;
  font-family: Manrope, sans-serif;
  font-size: 13px;
  font-weight: 700;
  letter-spacing: .04em;
  transition: background .2s ease, border-color .2s ease;
}

.admin-header-link:hover {
  border-color: #ce2b37;
  background: rgba(206, 43, 55, .2);
}

.admin-header-link span {
  margin-left: 7px;
  color: #fff;
}

.cart-toggle:hover {
  border-color: var(--accent);
  background: color-mix(in srgb, var(--brand-accent-deep) 9%, transparent);
}

.cart-toggle svg {
  width: 18px;
  height: 18px;
  fill: none;
  stroke: var(--accent);
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-width: 1.5;
}

.cart-toggle-label {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: .1em;
}

.cart-count {
  display: grid;
  min-width: 19px;
  height: 19px;
  place-items: center;
  border-radius: 50%;
  background: var(--accent);
  color: var(--accent-ink);
  font-size: 11px;
  font-weight: 700;
}

.menu-toggle {
  display: inline-flex;
  min-width: 91px;
  height: 43px;
  align-items: center;
  justify-content: center;
  gap: 4px;
  padding: 0 12px;
  border: 1px solid color-mix(in srgb, var(--brand-accent-deep) 42%, transparent);
  background: rgba(26, 26, 28, .55);
  color: var(--text);
  cursor: pointer;
  transition: border-color .2s ease, background .2s ease;
}

.menu-toggle:hover {
  transform: translateY(-1px);
  border-color: color-mix(in srgb, var(--brand-accent) 58%, transparent);
  background: rgba(26, 26, 28, .78);
  transition: transform .22s cubic-bezier(.22, .82, .22, 1), border-color .22s ease, background .22s ease;
}

.menu-toggle .catalog-menu-icon {
  transition: transform .22s cubic-bezier(.22, .82, .22, 1);
}

.menu-toggle:hover .catalog-menu-icon {
  transform: scale(1.08) rotate(3deg);
}

.cart-backdrop {
  position: fixed;
  z-index: 29;
  inset: 0;
  border: 0;
  background: rgba(1, 4, 8, .75);
  cursor: default;
  animation: backdrop-in .22s ease-out both;
  backdrop-filter: blur(5px);
}

.cart-drawer {
  position: fixed;
  z-index: 30;
  inset: 0 0 0 auto;
  display: flex;
  width: min(520px, 94vw);
  min-height: 100dvh;
  flex-direction: column;
  overflow-y: auto;
  padding: 35px clamp(23px, 4vw, 40px);
  border-left: 1px solid color-mix(in srgb, var(--brand-accent-deep) 20%, transparent);
  background: #101012;
  box-shadow: -30px 0 90px rgba(0, 0, 0, .35);
  animation: cart-in .38s cubic-bezier(.2, .8, .2, 1) both;
}

.cart-drawer-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  padding-bottom: 25px;
  border-bottom: 1px solid var(--line);
}

.cart-drawer-header h2 {
  margin: 11px 0 0;
  font-family: Manrope, sans-serif;
  font-size: 25px;
  font-weight: 600;
  letter-spacing: -.06em;
}

.cart-drawer-header h2 span {
  color: var(--muted);
  font-size: 15px;
}

.cart-empty {
  display: flex;
  flex: 1;
  flex-direction: column;
  align-items: flex-start;
  justify-content: center;
  padding: 35px 0;
}

.cart-empty > span {
  color: var(--accent);
  font-size: 36px;
}

.cart-empty h3 {
  margin: 15px 0 0;
  font-family: Manrope, sans-serif;
  font-size: 20px;
}

.cart-empty p,
.cart-actions > p {
  color: var(--muted);
  font-size: 13px;
  line-height: 1.8;
}

.cart-empty .button {
  margin-top: 15px;
}

.cart-items {
  flex: 1;
}

.cart-item {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 34px;
  align-items: center;
  gap: 12px;
  padding: 18px 0;
  border-bottom: 1px solid var(--line);
}

.cart-item-link {
  display: grid;
  min-width: 0;
  grid-template-columns: 90px minmax(0, 1fr);
  align-items: center;
  gap: 14px;
}

.cart-item-link:hover .cart-item-info h3 {
  color: var(--accent);
}

.cart-item-link > img {
  width: 90px;
  height: 68px;
  object-fit: cover;
}

.cart-item-info small {
  color: var(--muted);
  font-size: 10px;
  text-transform: uppercase;
}

.cart-item-info h3 {
  margin: 5px 0 7px;
  font-size: 14px;
  font-weight: 600;
}

.cart-item-info strong {
  color: var(--accent);
  font-size: 13px;
}

.cart-item-info .vehicle-original-price {
  color: var(--muted);
  font-size: 11px;
}

.cart-item-info .vehicle-vat-note {
  display: block;
  margin-top: 3px;
  font-size: 9px;
  text-transform: none;
}

.cart-remove {
  width: 32px;
  height: 32px;
  border: 1px solid var(--line);
  border-radius: 50%;
  background: transparent;
  color: var(--muted);
  cursor: pointer;
  font-size: 19px;
}

.cart-remove:hover {
  border-color: #ff9a91;
  color: #ff9a91;
}

.cart-actions {
  display: grid;
  gap: 13px;
  padding-top: 22px;
}

.cart-actions .button {
  width: 100%;
}

.clear-cart {
  justify-self: center;
  padding: 5px 10px;
  border: 0;
  background: none;
  color: var(--muted);
  cursor: pointer;
  font-size: 12px;
}

.clear-cart:hover {
  color: var(--text);
}

.menu-toggle:hover {
  border-color: var(--accent);
  background: color-mix(in srgb, var(--brand-accent-deep) 10%, transparent);
}

.menu-toggle-icon {
  display: grid;
  gap: 3px;
}

.menu-toggle-icon i {
  display: block;
  width: 13px;
  height: 1px;
  background: var(--accent);
  transition: width .2s ease;
}

.menu-toggle-icon i:nth-child(2) {
  width: 9px;
}

.menu-toggle:hover .menu-toggle-icon i:nth-child(2) {
  width: 13px;
}

.menu-toggle-label {
  margin-left: 7px;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: .16em;
}

.menu-backdrop {
  position: fixed;
  z-index: 29;
  inset: 0;
  border: 0;
  background: rgba(1, 4, 8, .75);
  cursor: default;
  animation: backdrop-in .22s ease-out both;
  backdrop-filter: blur(5px);
}

.menu-drawer {
  position: fixed;
  z-index: 30;
  inset: 0 auto 0 0;
  display: flex;
  width: min(460px, 91vw);
  min-height: 100dvh;
  flex-direction: column;
  overflow-y: auto;
  scrollbar-width: none;
  -ms-overflow-style: none;
  padding: 28px clamp(25px, 5vw, 55px) 25px;
  border-radius: 0;
  border-right: 1px solid color-mix(in srgb, var(--brand-accent-deep) 19%, transparent);
  background:
    radial-gradient(ellipse at 2% 28%, color-mix(in srgb, var(--brand-accent-deep) 8%, transparent), transparent 44%),
    #101012;
  box-shadow: 30px 0 90px rgba(0, 0, 0, .35);
  animation: drawer-in .38s cubic-bezier(.2, .8, .2, 1) both;
}

.menu-drawer::-webkit-scrollbar {
  display: none;
  width: 0;
  height: 0;
}

.menu-drawer,
.menu-backdrop {
  border-radius: 0 !important;
}

.menu-backdrop {
  width: 100vw !important;
  height: 100dvh !important;
  inset: 0 !important;
  border-radius: 0 !important;
}

.menu-drawer {
  left: 0 !important;
  right: auto !important;
  border-radius: 0 !important;
}

.drawer-topline {
  display: flex;
  min-height: 41px;
  align-items: center;
  justify-content: space-between;
}

.drawer-close {
  display: grid;
  width: 40px;
  height: 40px;
  place-items: center;
  border: 1px solid var(--line);
  border-radius: 50%;
  background: transparent;
  color: var(--text);
  cursor: pointer;
  font-size: 25px;
  transition: border-color .2s ease, color .2s ease, transform .2s ease;
}

.drawer-close:hover {
  transform: none;
  border-color: rgba(255, 255, 255, .32);
  color: var(--text);
}

.drawer-intro {
  margin: clamp(35px, 8vh, 78px) 0 28px;
}

.drawer-intro h2 {
  margin: 14px 0 0;
  font-family: Manrope, sans-serif;
  font-size: clamp(38px, 6vw, 52px);
  font-weight: 600;
  letter-spacing: -.075em;
  line-height: 1.02;
}

.drawer-intro h2 em {
  color: var(--accent);
  font-weight: 500;
}

.drawer-label {
  margin: 0 0 10px;
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: .18em;
}

.drawer-links {
  display: grid;
}

.drawer-links > a,
.drawer-links > button {
  display: flex;
  min-height: 54px;
  align-items: center;
  gap: 17px;
  padding: 0 6px;
  border: 0;
  border-top: 1px solid var(--line);
  background: transparent;
  color: #e9f1f8;
  cursor: pointer;
  font-family: Manrope, sans-serif;
  font-size: 15px;
  font-weight: 500;
  text-align: left;
  transition: none;
}

.drawer-links > :last-child {
  border-bottom: 1px solid var(--line);
}

.drawer-links > a > span:first-child,
.drawer-links > button > span:first-child {
  color: var(--accent);
  font-family: 'DM Sans', sans-serif;
  font-size: 11px;
}

.drawer-links > a:hover,
.drawer-links > button:hover {
  padding: 0 6px;
  color: var(--accent);
}

.drawer-arrow {
  margin-left: auto;
  color: var(--accent);
  font-size: 13px;
}

.drawer-secondary {
  display: flex;
  flex-wrap: wrap;
  gap: 10px 19px;
  padding: 22px 0;
}

.drawer-secondary a {
  color: var(--muted);
  font-size: 12px;
  transition: color .2s ease;
}

.drawer-secondary a:hover {
  color: var(--accent);
}

.drawer-account {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  padding-top: 5px;
}

.drawer-account .button {
  flex: 1 1 130px;
  min-height: 44px;
}

.drawer-account .user-greeting {
  flex: 1 0 100%;
  color: var(--muted);
  font-size: 12px;
}

.drawer-account .user-greeting strong {
  color: var(--text);
}

.drawer-footer {
  margin: auto 0 0;
  padding-top: 30px;
  color: #6d7b89;
  font-size: 10px;
  letter-spacing: .13em;
}

.button {
  display: inline-flex;
  min-height: 49px;
  align-items: center;
  justify-content: center;
  gap: 25px;
  padding: 0 21px;
  border: 1px solid transparent;
  border-radius: 3px;
  cursor: pointer;
  font-size: 14px;
  font-weight: 700;
  transition: background .2s ease, color .2s ease, border-color .2s ease, transform .2s ease;
}

.button:hover:not(:disabled) {
  transform: translateY(-2px);
}

.button:disabled {
  cursor: wait;
  opacity: .7;
}

.button-small {
  min-height: 38px;
  padding: 0 15px;
  gap: 13px;
}

.button-outline {
  border-color: color-mix(in srgb, var(--brand-accent-deep) 42%, transparent);
  background: transparent;
  color: white;
}

.vehicle-sale-process {
  display: grid;
  grid-template-columns: minmax(210px, .75fr) minmax(0, 1.65fr);
  align-items: center;
  gap: 24px 42px;
}

.dedicated-sell-page {
  padding-top: 1px;
}

.dedicated-sell-page .vehicle-sale-process {
  margin-top: 145px;
}

.dedicated-sell-page .sell-section {
  margin-top: 48px;
  margin-bottom: 90px;
}

.vehicle-sale-process-heading :is(h1, h2) {
  margin: 14px 0 12px;
  font-family: Manrope, sans-serif;
  font-size: clamp(31px, 3.4vw, 43px);
  font-weight: 600;
  letter-spacing: -.06em;
  line-height: 1.08;
}

.vehicle-sale-process-heading :is(h1, h2) em {
  color: var(--accent);
  font-weight: 500;
}

.vehicle-sale-process-heading > p:last-child {
  max-width: 380px;
  margin: 0;
  color: var(--muted);
  font-size: 12px;
  line-height: 1.8;
}

.vehicle-sale-steps {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  align-items: center;
  gap: 12px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.vehicle-sale-step {
  display: grid;
  grid-template-columns: 30px minmax(0, 1fr) auto;
  align-items: center;
  gap: 10px;
  min-width: 0;
}

.admin-discount-expiration-label {
  color: var(--muted);
  font-size: 11px;
  font-weight: 600;
}

.vehicle-sale-step:last-child {
  grid-template-columns: 30px minmax(0, 1fr);
}

.vehicle-sale-step-number {
  display: grid;
