  font-size: clamp(39px, 4.5vw, 57px);
  line-height: 1.08;
}

.section-intro {
  max-width: 280px;
  margin: 0 0 5px;
  color: var(--muted);
  font-size: 14px;
  line-height: 1.8;
}

.inventory-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  margin: 45px 0 22px;
  padding-bottom: 16px;
  border-bottom: 1px solid var(--line);
}

.filter-tabs {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
}

.filter-tab {
  padding: 10px 15px;
  border: 1px solid transparent;
  border-radius: 2px;
  background: transparent;
  color: var(--muted);
  cursor: pointer;
  font-size: 12px;
  transition: color .2s ease, border-color .2s ease, background .2s ease;
}

.filter-tab:hover {
  color: var(--text);
}

.filter-tab.is-active {
  border-color: var(--line);
  background: var(--surface);
  color: var(--accent);
}

.reset-filters {
  padding: 8px 0 8px 10px;
  border: 0;
  background: transparent;
  color: var(--muted);
  cursor: pointer;
  font-size: 12px;
}

.reset-filters:hover {
  color: var(--accent);
}

.advanced-filters {
  display: grid;
  grid-template-columns: minmax(190px, 1.5fr) repeat(5, minmax(120px, 1fr));
  gap: 11px;
  align-items: end;
  margin: 20px 0 12px;
}

.advanced-filters .search-field {
  width: 100%;
}

.filter-control {
  display: grid;
  gap: 7px;
  color: var(--muted);
  font-size: 11px;
}

.filter-control select {
  width: 100%;
  min-width: 0;
  height: 39px;
  padding: 0 10px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: #151518;
  color: var(--text);
  font-size: 12px;
}

.filter-control select:focus-visible {
  outline-color: var(--accent);
}

.results-count {
  margin: 17px 0 10px;
  color: var(--muted);
  font-size: 11px;
  scroll-margin-top: 112px;
}

.search-field {
  display: flex;
  width: 218px;
  align-items: center;
  gap: 9px;
  padding-bottom: 8px;
  border-bottom: 1px solid var(--line);
  color: var(--muted);
}

.search-icon {
  font-size: 20px;
  line-height: 1;
}

.search-field input {
  width: 100%;
  border: 0;
  outline: 0;
  background: transparent;
  color: var(--text);
  font-size: 12px;
}

.search-field input::placeholder {
  color: #777a72;
}

.search-field input:focus-visible {
  outline: 0;
}

.vehicle-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 18px;
}

.vehicle-grid.is-loading-or-error {
  min-height: 180px;
}

.vehicle-grid > .content-error-state {
  grid-column: 1 / -1;
}

.content-error-state {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: 16px;
  padding: 21px 23px;
  border: 1px solid rgba(255, 154, 145, .2);
  border-radius: 12px;
  background:
    radial-gradient(ellipse at 0 0, rgba(255, 116, 105, .09), transparent 62%),
    linear-gradient(135deg, rgba(20, 19, 22, .96), rgba(9, 12, 17, .98));
  box-shadow: inset 0 1px rgba(255, 255, 255, .035), 0 14px 36px rgba(0, 0, 0, .13);
}

.content-error-icon {
  display: grid;
  width: 42px;
  height: 42px;
  flex: 0 0 auto;
  place-items: center;
  border: 1px solid rgba(255, 154, 145, .22);
  border-radius: 50%;
  background: rgba(255, 116, 105, .09);
  color: #ffaaa1;
}

.content-error-icon svg {
  width: 21px;
  height: 21px;
}

.content-error-copy {
  min-width: 0;
  flex: 1;
}

.content-error-copy h3 {
  margin: 0 0 5px;
  color: #f5f2f1;
  font-family: Manrope, sans-serif;
  font-size: 14px;
  font-weight: 650;
  letter-spacing: -.02em;
}

.content-error-copy p {
  margin: 0;
  color: #a4abb4;
  font-size: 12px;
  line-height: 1.65;
  overflow-wrap: anywhere;
}

.vehicle-novice-note {
  display: flex;
  gap: 8px;
  margin: -10px 0 20px;
  padding: 11px 12px;
  border-left: 2px solid #d5ae59;
  background: rgba(213, 174, 89, .07);
  color: #c6b889;
  font-size: 10px;
  line-height: 1.6;
}

.vehicle-maintenance-history {
  margin: 0 0 22px;
  padding: 17px 0;
  border-top: 1px solid var(--line);
  background: transparent;
}

.vehicle-maintenance-history h2 {
  display: flex;
  align-items: center;
  gap: 8px;
  margin: 0 0 8px;
  font-size: 12px;
}

.vehicle-maintenance-history h2 .site-icon {
  width: 16px;
  height: 16px;
  color: var(--accent);
}

.vehicle-maintenance-history p {
  margin: 0;
  color: var(--muted);
  font-size: 13px;
  line-height: 1.7;
  white-space: pre-line;
}

.content-error-retry {
  display: inline-flex;
  min-height: 38px;
  flex: 0 0 auto;
  align-items: center;
  gap: 8px;
  padding: 0 13px;
  border: 1px solid rgba(255, 255, 255, .14);
  border-radius: 7px;
  background: rgba(255, 255, 255, .045);
  color: #f1f5fa;
  font-size: 11px;
  font-weight: 600;
  cursor: pointer;
  transition: border-color .2s ease, background .2s ease, transform .2s ease;
}

.content-error-retry:hover {
  transform: translateY(-1px);
  border-color: rgba(255, 170, 161, .38);
  background: rgba(255, 116, 105, .09);
}

.content-error-retry span {
  color: #ffaaa1;
  font-size: 16px;
  line-height: 1;
}

.skeleton-shimmer {
  background: linear-gradient(100deg, #181818 20%, #303030 42%, #181818 64%);
  background-size: 220% 100%;
  animation: content-skeleton-shimmer 1.5s ease-in-out infinite;
}

.skeleton-line {
  height: 10px;
  border-radius: 999px;
}

.skeleton-line-short {
  width: 38%;
}

.skeleton-line-medium {
  width: 68%;
}

.skeleton-line-title {
  width: 78%;
  height: 17px;
  border-radius: 5px;
}

.vehicle-card-skeleton {
  overflow: hidden;
  border: 1px solid rgba(255, 255, 255, .08);
  background: var(--surface);
}

.vehicle-skeleton-image {
  height: 224px;
}

.vehicle-skeleton-content {
  display: grid;
  gap: 14px;
  padding: 17px;
}

.vehicle-skeleton-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-top: 3px;
}

.skeleton-line-price {
  width: 32%;
  height: 18px;
}

.skeleton-button {
  width: 92px;
  height: 32px;
  border-radius: 6px;
}

.inventory-feedback {
  margin: 15px 0 0;
  color: var(--muted);
  font-size: 11px;
}

.vehicle-card {
  overflow: hidden;
  border: 1px solid rgba(255, 255, 255, .08);
  background: var(--surface);
  transition: border-color .2s ease, transform .2s ease;
}

.vehicle-card:hover {
  transform: translateY(-4px);
  border-color: color-mix(in srgb, var(--brand-accent-deep) 38%, transparent);
}

.site-shell.catalog-page-shell .catalog-page-section .vehicle-card:hover {
  border-color: #303034;
  box-shadow: 0 16px 34px rgba(0, 0, 0, .34);
  transform: none;
}

.site-shell.catalog-page-shell .catalog-page-section .vehicle-card,
.site-shell.catalog-page-shell .catalog-page-section .vehicle-card:hover,
.site-shell.catalog-page-shell .catalog-page-section .vehicle-card:focus,
.site-shell.catalog-page-shell .catalog-page-section .vehicle-card:focus-within {
  border: 1px solid #303034 !important;
  border-color: #303034 !important;
  box-shadow: 0 16px 34px rgba(0, 0, 0, .34) !important;
  transform: none;
  outline: none;
  transition: box-shadow .22s ease, border-color .22s ease;
}

.vehicle-image-wrap {
  position: relative;
  height: 224px;
  overflow: hidden;
  background: #1a1a1c;
}

.vehicle-image-wrap::after {
  position: absolute;
  inset: 45% 0 0;
  background: linear-gradient(0deg, rgba(0, 0, 0, .4), transparent);
  content: '';
  pointer-events: none;
}

.vehicle-image-wrap img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform .5s ease;
}

.vehicle-card:hover .vehicle-image-wrap img {
  transform: scale(1.04);
}

.vehicle-label,
.vehicle-type {
  position: absolute;
  z-index: 1;
  top: 13px;
  padding: 7px 9px;
  background: rgba(16, 17, 15, .78);
  color: #f2f1e9;
  font-size: 10px;
  letter-spacing: .07em;
}

.vehicle-label {
  left: 13px;
}

.vehicle-type {
  right: 13px;
  color: var(--accent);
}

.vehicle-engagement {
  position: absolute;
  z-index: 2;
  right: 12px;
  bottom: 12px;
  left: 12px;
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  pointer-events: none;
}

.vehicle-engagement span {
  display: inline-flex;
  min-height: 27px;
  align-items: center;
  gap: 6px;
  padding: 5px 8px;
  border: 1px solid rgba(224, 235, 246, .17);
  border-radius: 7px;
  background: rgba(23, 23, 25, .78);
  box-shadow: 0 4px 12px rgba(0, 0, 0, .28), inset 0 1px rgba(255, 255, 255, .055);
  color: #e7eef5;
  font-size: 10px;
  line-height: 1;
  -webkit-backdrop-filter: blur(10px);
  backdrop-filter: blur(10px);
}

.site-shell .vehicle-engagement .site-icon {
  width: 14px;
  height: 14px;
  color: var(--accent);
}

.vehicle-info {
  padding: 20px 19px 17px;
}

.vehicle-title-row,
.vehicle-price-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.vehicle-make {
  margin: 0;
  color: var(--muted);
  font-size: 11px;
  letter-spacing: .1em;
  text-transform: uppercase;
}

.vehicle-title-row h3 {
  margin: 6px 0 0;
  font-family: Manrope, sans-serif;
  font-size: 17px;
  font-weight: 600;
  letter-spacing: -.04em;
}

.vehicle-arrow {
  display: grid;
  width: 31px;
  height: 31px;
  place-items: center;
  border: 1px solid var(--line);
  border-radius: 50%;
  color: var(--accent);
}

.vehicle-meta {
  display: flex;
  align-items: center;
  gap: 9px;
  margin: 17px 0;
  color: var(--muted);
  font-size: 11px;
}

.meta-divider {
  width: 3px;
  height: 3px;
  border-radius: 50%;
  background: var(--accent);
}

.vehicle-price-row {
  padding-top: 14px;
  border-top: 1px solid var(--line);
}

.vehicle-price-row strong {
  font-size: 14px;
  font-weight: 600;
  white-space: nowrap;
}

.vehicle-price-value {
  display: grid;
  min-width: 0;
  gap: 4px;
}

.vehicle-original-price {
  color: var(--muted);
  font-size: 11px;
  font-weight: 500;
}

.vehicle-discount-price-line {
  display: flex;
  width: 100%;
  min-width: 0;
  align-items: baseline;
  flex-wrap: wrap;
  gap: 7px;
}

.vehicle-discount-countdown {
  display: inline-flex;
  flex: 0 0 auto;
  align-items: center;
  justify-self: end;
  gap: 6px;
  margin-left: auto;
  margin-top: 3px;
  padding: 4px 8px;
  border: 1px solid rgba(139, 234, 171, .26);
  border-radius: 6px;
  background: rgba(67, 151, 94, .12);
  color: #8beaab;
  font-size: 11px;
  font-variant-numeric: tabular-nums;
  font-weight: 700;
  line-height: 1.3;
  white-space: nowrap;
}

.vehicle-discount-permanent {
  justify-self: end;
  margin-left: auto;
  color: var(--muted);
  font-size: 10px;
  font-weight: 600;
}

.vehicle-discount-countdown svg {
  width: 12px;
  height: 12px;
  flex: 0 0 12px;
  fill: none;
  stroke: currentColor;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-width: 1.5;
}

.vehicle-discount-badge {
  display: inline-flex;
  align-items: center;
  width: fit-content;
  color: #fff;
  background: var(--accent);
  border-radius: 999px;
  padding: 3px 7px;
  font-size: 9px;
  line-height: 1.2;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: .04em;
  text-decoration-color: rgba(255, 255, 255, .5);
}

.vehicle-vat-note,
.vehicle-detail-vat-note {
  color: var(--muted);
  font-size: 9px;
  font-weight: 500;
  line-height: 1.4;
  white-space: normal;
}

.vehicle-detail-vat-note {
  font-size: 10px;
  text-align: right;
}

.vehicle-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 12px;
}

.vehicle-enquire,
.vehicle-add,
.service-card a,
.service-card button {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  padding: 0;
  border: 0;
  background: transparent;
  color: var(--accent);
  cursor: pointer;
  font-size: 12px;
  font-weight: 600;
  transition: color .2s ease;
}

.vehicle-enquire:hover {
  color: white;
}

.vehicle-add {
  min-height: 31px;
  padding: 0 9px;
  border: 1px solid color-mix(in srgb, var(--brand-accent-deep) 36%, transparent);
  border-radius: 2px;
  color: var(--accent);
}

.vehicle-add-icon {
  width: 16px;
  height: 16px;
  flex: 0 0 auto;
  fill: none;
  stroke: currentColor;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-width: 1.5;
}

.vehicle-add:hover,
.vehicle-add.is-added {
  background: rgba(255, 255, 255, .06);
}

.inventory-note {
  margin: 24px 0 0;
  color: #777a72;
  font-size: 12px;
  text-align: center;
}

.catalog-pagination {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 20px;
  margin: 30px 0 12px;
}

.catalog-page-button {
  display: inline-flex;
  min-height: 42px;
  align-items: center;
  justify-content: center;
  gap: 9px;
  padding: 9px 14px;
  border: 1px solid var(--line);
  border-radius: 7px;
  background: rgba(255, 255, 255, .025);
  color: var(--text);
  cursor: pointer;
  font-size: 12px;
  font-weight: 600;
  transition: border-color .2s ease, background .2s ease, color .2s ease;
}

.catalog-page-button:not(:disabled):hover {
  border-color: color-mix(in srgb, var(--accent) 45%, var(--line));
  background: color-mix(in srgb, var(--accent) 8%, transparent);
  color: var(--accent);
}

.catalog-page-button:disabled {
  cursor: not-allowed;
  opacity: .42;
}

.catalog-page-button:focus-visible,
.catalog-recommendation-card:focus-visible {
  outline: 2px solid color-mix(in srgb, var(--accent) 70%, transparent);
  outline-offset: 3px;
}

.catalog-page-indicator {
  color: var(--muted);
  font-size: 12px;
  white-space: nowrap;
}

.catalog-page-indicator strong {
  color: var(--text);
}

.catalog-recommendations {
  margin-top: 55px;
  padding-top: 32px;
  border-top: 1px solid var(--line);
}

.catalog-recommendations-heading {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 20px;
}

.catalog-recommendations-heading .eyebrow {
  margin: 0;
  color: var(--accent);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: .14em;
}

.catalog-recommendations-heading h2 {
  margin: 9px 0 0;
  font-family: Manrope, sans-serif;
  font-size: clamp(24px, 3vw, 32px);
  font-weight: 600;
  letter-spacing: -.05em;
}

.catalog-recommendations-heading h2 em {
  color: var(--accent);
  font-weight: 500;
}

.catalog-recommendations-heading > p {
  max-width: 340px;
  margin: 0;
  color: var(--muted);
  font-size: 11px;
  line-height: 1.65;
}

.catalog-recommendations-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 12px;
}

.catalog-recommendation-card {
  position: relative;
  display: flex;
  min-width: 0;
  align-items: center;
  gap: 13px;
  padding: 10px;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 9px;
  background: linear-gradient(145deg, rgba(255, 255, 255, .045), rgba(255, 255, 255, .012));
  color: var(--text);
  text-align: left;
  cursor: pointer;
  transition: transform .2s ease, border-color .2s ease, background .2s ease;
}

.catalog-recommendation-card:hover {
  transform: translateY(-2px);
  border-color: color-mix(in srgb, var(--accent) 42%, var(--line));
  background: color-mix(in srgb, var(--accent) 5%, var(--surface));
}

.catalog-recommendation-card > img {
  width: 92px;
  height: 74px;
  flex: 0 0 auto;
  border-radius: 5px;
  background: var(--surface);
  object-fit: cover;
}

.catalog-recommendation-info {
  display: grid;
  min-width: 0;
  gap: 4px;
}

.catalog-recommendation-info small {
  color: var(--accent);
  font-size: 8px;
  font-weight: 700;
  letter-spacing: .08em;
}

.catalog-recommendation-info strong,
.catalog-recommendation-info > span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.catalog-recommendation-info strong {
  font-size: 12px;
}

.catalog-recommendation-info > span {
  color: var(--muted);
  font-size: 10px;
}

.catalog-recommendation-info em {
  color: var(--text);
  font-size: 11px;
  font-style: normal;
  font-weight: 700;
}

.catalog-recommendation-info .vehicle-original-price {
  font-size: 9px;
}

.catalog-recommendation-info .vehicle-vat-note {
  color: var(--muted);
  font-size: 9px;
  letter-spacing: 0;
  text-transform: none;
}

.catalog-recommendation-arrow {
  margin-left: auto;
  color: var(--accent);
}

.empty-results {
  grid-column: 1 / -1;
  display: grid;
  justify-items: center;
  gap: 10px;
  padding: 45px 18px;
  color: var(--muted);
  font-size: 13px;
  text-align: center;
}

.empty-results strong {
  color: var(--text);
  font-family: Manrope, sans-serif;
  font-size: 18px;
}

.empty-results p {
  max-width: 480px;
  margin: 0 0 5px;
  line-height: 1.7;
}

.sold-cars-section {
  padding-top: 54px;
  padding-bottom: 76px;
}

.sold-cars-section .section-heading {
  align-items: center;
  flex-direction: column;
  gap: 12px;
  text-align: center;
}

.sold-cars-section .section-intro {
  max-width: min(560px, 100%);
  margin: 0;
  text-align: center;
}

.horizontal-carousel-frame {
  position: relative;
  isolation: isolate;
}

.horizontal-carousel-frame::before,
.horizontal-carousel-frame::after {
  position: absolute;
  z-index: 4;
  top: 0;
  bottom: 0;
  width: clamp(42px, 8vw, 112px);
  content: '';
  pointer-events: none;
}

.horizontal-carousel-frame::before {
  left: 0;
  background: linear-gradient(90deg, rgba(0, 0, 0, .66), rgba(0, 0, 0, .28) 42%, transparent);
  box-shadow: inset 12px 0 22px -20px rgba(0, 0, 0, .9);
}

.horizontal-carousel-frame::after {
  right: 0;
  background: linear-gradient(270deg, rgba(0, 0, 0, .66), rgba(0, 0, 0, .28) 42%, transparent);
  box-shadow: inset -12px 0 22px -20px rgba(0, 0, 0, .9);
}

.sold-cars-grid {
  display: flex;
  flex-wrap: nowrap;
  overflow-x: auto;
  overflow-y: hidden;
  gap: 20px;
  margin-top: 34px;
  padding: 38px 0 42px;
  scroll-snap-type: x mandatory;
  scroll-padding-inline: 0;
  scrollbar-width: none;
  -ms-overflow-style: none;
  overscroll-behavior-inline: contain;
  perspective: 1100px;
}

.sold-cars-grid > :first-child,
.customer-reviews-grid > :first-child {
  margin-inline-start: auto;
}

.sold-cars-grid > :last-child,
.customer-reviews-grid > :last-child {
  margin-inline-end: auto;
}

.sold-cars-grid::-webkit-scrollbar,
.customer-reviews-grid::-webkit-scrollbar {
  display: none;
}

.sold-car-skeleton {
  flex: 0 0 calc((100% - 120px) / 7);
  scroll-snap-align: start;
  overflow: hidden;
  border: 1px solid rgba(220, 220, 220, .1);
  border-radius: 14px;
  background: linear-gradient(150deg, rgba(20, 28, 38, .92), rgba(7, 10, 14, .98));
}

.sold-skeleton-image {
  height: clamp(170px, 21vw, 245px);
}

.sold-skeleton-content {
  display: grid;
  gap: 13px;
  padding: 18px 19px 21px;
}

.sold-car-card {
  position: relative;
  flex: 0 0 calc((100% - 120px) / 7);
  min-width: 0;
  scroll-snap-align: start;
  overflow: hidden;
  border: 1px solid rgba(220, 220, 220, .1);
  border-radius: 14px;
  background: linear-gradient(150deg, rgba(20, 28, 38, .92), rgba(7, 10, 14, .98));
  box-shadow: 0 12px 30px rgba(0, 0, 0, .14), inset 0 1px rgba(255, 255, 255, .035);
  transform: translateY(0) rotateX(0) rotateY(0);
  transform-style: preserve-3d;
  transition: transform .45s cubic-bezier(.2, .75, .25, 1), border-color .35s ease, box-shadow .4s ease;
}

.sold-car-card::before {
  position: absolute;
  z-index: 1;
  inset: auto 0 0;
  height: 2px;
  background: linear-gradient(90deg, transparent, var(--accent), transparent);
  content: '';
  opacity: .35;
  transform: scaleX(.35);
  transition: opacity .35s ease, transform .45s ease;
}

.sold-car-card:hover {
  z-index: 2;
  border-color: rgba(212, 219, 226, .28);
  box-shadow: 0 24px 54px rgba(0, 0, 0, .52), inset 0 1px rgba(255, 255, 255, .055);
  transform: translateY(-7px) rotateX(1deg);
}

.sold-car-card:hover::before {
  opacity: .9;
  transform: scaleX(1);
}

.sold-car-image {
  position: relative;
  height: clamp(170px, 21vw, 245px);
  overflow: hidden;
  background: #1a1a1c;
}

.sold-car-image::after {
  position: absolute;
  inset: 30% 0 0;
  background: linear-gradient(180deg, transparent, rgba(4, 7, 10, .56));
  content: '';
  pointer-events: none;
}

.sold-car-image::before {
  position: absolute;
  z-index: 1;
  top: 0;
  left: -85%;
  width: 48%;
  height: 100%;
  background: linear-gradient(105deg, transparent, rgba(255, 255, 255, .13), transparent);
  content: '';
  pointer-events: none;
  transform: skewX(-15deg);
  transition: left .75s cubic-bezier(.2, .75, .25, 1);
}

.sold-car-image img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
  filter: saturate(.78) contrast(1.02);
  transform: scale(1.025);
  transition: transform .75s cubic-bezier(.2, .75, .25, 1), filter .5s ease;
}

.sold-car-card:hover .sold-car-image img {
  transform: scale(1.09);
  filter: saturate(1.08) contrast(1.04);
}

.sold-car-card:hover .sold-car-image::before {
  left: 140%;
}

.sold-car-image > .sold-car-status {
  position: absolute;
  z-index: 2;
  right: 12px;
  bottom: 12px;
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 7px 10px;
  border: 1px solid rgba(182, 232, 205, .2);
  border-radius: 999px;
  background: rgba(3, 8, 7, .76);
  backdrop-filter: blur(12px);
  color: #b6e8cd;
  font-size: 9px;
  font-weight: 700;
  letter-spacing: .13em;
  transition: border-color .3s ease, transform .3s ease;
}

.sold-car-status > i {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: #86d8a8;
  box-shadow: 0 0 0 0 rgba(134, 216, 168, .5);
  animation: delivery-status-pulse 2.2s ease-out infinite;
}

.sold-car-card:hover .sold-car-status {
  border-color: rgba(182, 232, 205, .42);
  transform: translateY(-2px);
}

.sold-car-info {
  position: relative;
  padding: 17px 19px 19px;
}

.sold-car-info > p {
  display: flex;
  align-items: center;
  gap: 8px;
  margin: 0 0 8px;
  color: #9eabb9;
  font-size: 9px;
  font-weight: 600;
  letter-spacing: .1em;
  text-transform: uppercase;
}

.sold-car-info > p::before {
  width: 16px;
  height: 1px;
  background: var(--accent);
  content: '';
  opacity: .75;
}

.sold-car-info h3 {
  margin: 0;
  font-family: Manrope, sans-serif;
  font-size: clamp(16px, 1.5vw, 19px);
  font-weight: 600;
  letter-spacing: -.035em;
}

.sold-car-info h3 em {
  color: var(--accent);
  font-weight: 500;
}

.sold-cars-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  margin-top: 23px;
  padding-top: 17px;
  border-top: 1px solid var(--line);
  color: var(--muted);
  font-size: 11px;
}

.sold-cars-footer button {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  padding: 8px 0 8px 12px;
  border: 0;
  background: transparent;
  color: var(--accent);
  cursor: pointer;
  font-size: 11px;
  font-weight: 700;
  transition: gap .25s ease, color .25s ease;
}

.sold-cars-footer button:hover,
.sold-cars-footer button:focus-visible {
  gap: 13px;
  color: #c4e6ff;
}

.sold-cars-empty {
  margin: 25px 0 0;
  padding: 26px 20px;
  border: 1px dashed rgba(220, 220, 220, .17);
  border-radius: 12px;
  background: rgba(255, 255, 255, .012);
  color: var(--muted);
  font-size: 12px;
  text-align: center;
}

@keyframes delivery-story-arrive {
  from {
    opacity: 0;
    transform: translateY(22px) scale(.985);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

@keyframes delivery-status-pulse {
  0% { box-shadow: 0 0 0 0 rgba(134, 216, 168, .48); }
  70% { box-shadow: 0 0 0 6px rgba(134, 216, 168, 0); }
  100% { box-shadow: 0 0 0 0 rgba(134, 216, 168, 0); }
}

.vehicle-detail {
  min-height: calc(100vh - 94px);
  padding-top: 135px;
  padding-bottom: 100px;
}

.detail-back {
  justify-content: flex-start;
  gap: 12px;
  margin-bottom: 35px;
  padding: 0 17px;
}

.vehicle-detail-heading {
