}

.vehicle-detail-panel {
  padding: clamp(20px, 2.5vw, 30px);
  border: 1px solid rgba(220, 220, 220, .11);
  border-radius: 14px;
  background: linear-gradient(150deg, rgba(15, 21, 29, .94), rgba(7, 10, 14, .98));
