}

.site-shell.admin-site-shell.admin-authenticated-shell .admin-site-toggle {
  display: flex;
  align-items: center;
  gap: 9px;
  margin-top: 14px;
  color: #c8d1ca;
  font-size: 11px;
}

.site-shell.admin-site-shell.admin-authenticated-shell .admin-site-toggle-danger {
