}

.site-shell.admin-site-shell.admin-authenticated-shell .admin-availability-message {
  max-width: 600px;
  margin: 12px 0;
}

.site-shell.admin-site-shell.admin-authenticated-shell .admin-account-list {
  display: grid;
  gap: 8px;
  margin: 14px 0 20px;
}

.site-shell.admin-site-shell.admin-authenticated-shell .admin-account-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  padding: 12px;
  border: 1px solid #252b27;
  border-radius: 7px;
  background: #090c0a;
}

.site-shell.admin-site-shell.admin-authenticated-shell .admin-account-row > div:first-child {
  display: grid;
  gap: 4px;
  min-width: 0;
}

.site-shell.admin-site-shell.admin-authenticated-shell .admin-account-row strong {
