}

.site-shell.admin-site-shell.admin-authenticated-shell .admin-account-invite-form {
  padding-top: 17px;
  border-top: 1px solid #252b27;
}

.site-shell.admin-site-shell.admin-authenticated-shell .admin-account-invite-form > button,
.site-shell.admin-site-shell.admin-authenticated-shell .admin-account-verification-form > button {
