.site-shell.admin-site-shell.admin-authenticated-shell .admin-account-verification-form {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(180px, .6fr) auto;
  align-items: end;
  gap: 12px;
  margin-top: 16px;
  padding: 14px;
  border: 1px solid rgba(55, 170, 88, .3);
  border-radius: 8px;
  background: rgba(27, 79, 41, .12);
}

.site-shell.admin-site-shell.admin-authenticated-shell .admin-account-verification-form > div {
  display: grid;
  gap: 5px;
  color: #dce5de;
  font-size: 11px;
}

.site-shell.admin-site-shell.admin-authenticated-shell .admin-account-verification-form > div span {
  color: #87928a;
  font-size: 10px;
}

.site-shell.admin-site-shell.admin-authenticated-shell .admin-account-revoke-form {
  display: flex;
  align-items: end;
  gap: 8px;
