@media (max-width: 760px) {
  .site-shell.has-site-announcement {
    --site-announcement-height: 52px !important;
  }

  .site-announcement-banner {
    min-height: 52px;
    flex-direction: column;
    justify-content: center;
    gap: 2px;
    padding: 5px 12px;
  }

  .site-announcement-banner span {
    max-width: calc(100vw - 24px);
    font-size: 11px;
  }

  .site-announcement-banner small {
    font-size: 9px;
  }

  .site-shell.admin-site-shell.admin-authenticated-shell .admin-site-assets,
  .site-shell.admin-site-shell.admin-authenticated-shell .admin-utility-fields {
    grid-template-columns: minmax(0, 1fr);
  }

  .site-shell.admin-site-shell.admin-authenticated-shell .admin-opening-hours-row {
    grid-template-columns: minmax(0, 1fr) auto;
  }

  .site-shell.admin-site-shell.admin-authenticated-shell .admin-opening-time-fields {
    grid-column: 1 / -1;
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .site-shell.admin-site-shell.admin-authenticated-shell .admin-holiday-add,
  .site-shell.admin-site-shell.admin-authenticated-shell .admin-account-verification-form {
    grid-template-columns: minmax(0, 1fr);
  }

  .site-shell.admin-site-shell.admin-authenticated-shell .admin-account-row,
  .site-shell.admin-site-shell.admin-authenticated-shell .admin-account-revoke-form {
    align-items: stretch;
    flex-direction: column;
  }
}

@media (max-width: 620px) {
  .content-error-state {
    align-items: flex-start;
    flex-wrap: wrap;
    gap: 12px;
    padding: 17px;
  }

  .content-error-icon {
    width: 36px;
    height: 36px;
  }

  .content-error-copy {
    flex-basis: calc(100% - 50px);
    padding-top: 2px;
  }

  .content-error-retry {
    margin-left: 48px;
  }
}

.admin-page {
  min-height: 100vh;
  padding-top: 145px;
  padding-bottom: 90px;
}

.admin-heading {
  display: flex;
