  border: 1px solid rgba(139, 224, 173, .2);
  background:
    radial-gradient(ellipse at 0 0, rgba(139, 224, 173, .075), transparent 55%),
    linear-gradient(135deg, #111714, #090d0b 72%);
  box-shadow: inset 4px 0 #8be0ad, 0 15px 44px rgba(0, 0, 0, .24);
}

.admin-heading-prominent .eyebrow {
  color: #8be0ad;
}

.admin-heading-prominent h1 {
  margin-top: 6px;
}

.admin-heading-prominent .admin-heading-actions .button-accent {
  border-color: #8be0ad;
  background: #8be0ad;
  color: #101612;
}

.admin-heading-prominent .admin-heading-actions .button-outline {
  border-color: rgba(190, 210, 196, .26);
  background: rgba(255, 255, 255, .025);
  color: #e7efe9;
}

.account-page {
  min-height: 100vh;
  padding-top: 145px;
  padding-bottom: 90px;
}

.account-page-heading {
  max-width: 760px;
  margin-bottom: 26px;
}

.account-page-heading h1 {
  margin: 9px 0;
  font-family: Manrope, sans-serif;
  font-size: clamp(34px, 5vw, 52px);
  font-weight: 600;
  letter-spacing: -.06em;
}

.account-page-heading h1 em {
  color: var(--accent);
  font-weight: 500;
}

.account-page-heading > p:last-child {
  color: var(--muted);
  font-size: 14px;
  line-height: 1.7;
}

.account-page-nav {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin: 22px 0 30px;
  padding-bottom: 14px;
  border-bottom: 1px solid var(--line);
}

.account-page-nav button {
  min-height: 42px;
  padding: 0 15px;
  border: 1px solid var(--line);
  background: #1c1c1f;
  color: var(--muted);
  cursor: pointer;
  font: inherit;
  font-size: 13px;
}

.admin-section-navigation {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 170px), 1fr));
  align-items: stretch;
}

.admin-section-navigation button {
  display: flex;
  min-width: 0;
  min-height: 48px;
  align-items: center;
  justify-content: center;
  gap: 8px;
  text-align: center;
  line-height: 1.25;
}

.account-page-nav button:hover,
.account-page-nav button.is-active {
  border-color: color-mix(in srgb, var(--brand-accent-deep) 55%, transparent);
  background: color-mix(in srgb, var(--brand-accent-deep) 10%, transparent);
  color: var(--text);
}

.account-page .customer-requests {
  padding: 15px 0 36px;
  border-top: 0;
}

.account-page .customer-purchases {
  margin-top: 28px;
}

.account-page .customer-purchases-heading h2 {
  margin: 7px 0;
  font-family: Manrope, sans-serif;
  font-size: 26px;
  font-weight: 600;
}

.admin-purchase-summary {
  display: flex;
  align-items: center;
  gap: 13px;
  padding: 10px;
  border: 1px solid var(--line);
  background: #1a1a1d;
}

.admin-purchase-accept {
  display: inline-flex;
  min-height: 38px;
  align-items: center;
  gap: 9px;
  margin-top: 12px;
  padding: 0 14px;
  border: 1px solid rgba(115, 223, 160, .42);
  border-radius: 6px;
  background: rgba(46, 160, 92, .1);
  color: #a4e9bb;
  cursor: pointer;
  font: inherit;
  font-size: 12px;
  font-weight: 600;
  transition: background .2s ease, border-color .2s ease, transform .2s ease;
}

.admin-purchase-accept:hover:not(:disabled) {
  transform: translateY(-1px);
  border-color: rgba(115, 223, 160, .75);
  background: rgba(46, 160, 92, .2);
}

.admin-purchase-accept:focus-visible {
  outline: 2px solid #8be1ad;
  outline-offset: 2px;
}

.admin-purchase-accept:disabled {
  cursor: wait;
  opacity: .7;
}

.admin-purchase-accept svg {
  width: 16px;
  height: 16px;
  flex: 0 0 auto;
  fill: none;
  stroke: currentColor;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-width: 1.8;
}

.admin-purchase-summary > .admin-purchase-image {
  width: 98px;
  height: 66px;
  flex: 0 0 auto;
}

.admin-purchase-summary > div {
  display: grid;
  gap: 5px;
}

.admin-purchase-summary span,
.admin-purchase-summary a {
  color: var(--muted);
  font-size: 13px;
}

.admin-purchase-summary a {
  color: var(--accent);
}

.offer-counter-highlight {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  margin: 14px 0;
  padding: 15px 17px;
  border: 1px solid rgba(0, 146, 70, .5);
  background: linear-gradient(100deg, rgba(0, 146, 70, .13), rgba(0, 146, 70, .035));
  color: #b6e8cd;
}

.offer-counter-highlight span {
  color: #d3d9df;
}

.offer-counter-highlight strong {
  color: #b6e8cd;
