  font-size: clamp(21px, 3vw, 28px);
}

.confirm-backdrop {
  z-index: 60;
}

.confirm-modal {
  width: min(100% - 32px, 480px);
  padding: 30px;
  border: 1px solid rgba(206, 43, 55, .4);
  background: linear-gradient(145deg, #11151c, #1c1c1f 72%);
  box-shadow: 0 24px 80px rgba(0, 0, 0, .55);
}

.confirm-icon {
  display: grid;
  width: 38px;
  height: 38px;
  place-items: center;
  margin-bottom: 18px;
  border: 1px solid rgba(206, 43, 55, .6);
  border-radius: 50%;
  color: #ff9a91;
  font-family: Manrope, sans-serif;
  font-size: 22px;
}

.confirm-modal h2 {
  margin: 0;
  font-family: Manrope, sans-serif;
  font-size: 25px;
}

.confirm-modal > p:not(.eyebrow):not(.form-error) {
  color: var(--muted);
  font-size: 15px;
  line-height: 1.65;
}

.confirm-actions {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
  margin-top: 22px;
}

.button-danger {
  border: 1px solid #ce2b37;
  background: #ce2b37;
  color: #fff;
}

.button-danger:hover {
  background: #a8202b;
}

.admin-layout {
  display: grid;
  grid-template-columns: minmax(0, 1.15fr) minmax(320px, .85fr);
  align-items: start;
  gap: 24px;
}

.admin-vehicle-form,
.admin-inventory {
  padding: 25px;
  border: 1px solid var(--line);
  background: var(--surface);
}

.admin-vehicle-form {
