  justify-content: space-between;
  gap: 15px;
  margin-bottom: 20px;
}

.admin-form-heading h2,
.admin-inventory h2 {
  margin: 0;
  font-family: Manrope, sans-serif;
  font-size: 18px;
  font-weight: 600;
}

.admin-form-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  align-items: start;
  gap: 14px;
  margin-bottom: 15px;
