.admin-specs-heading > .site-icon {
  width: 18px;
  height: 18px;
  flex: 0 0 auto;
}

.admin-specs-heading > span {
  display: grid;
  gap: 4px;
}

.admin-specs-heading strong {
  color: var(--text);
  font-size: 13px;
}

.admin-specs-heading small {
  color: var(--muted);
  font-size: 11px;
  line-height: 1.5;
