.admin-photo-hint {
  margin: 6px 0 11px;
  color: var(--muted);
  font-size: 12px;
  line-height: 1.6;
}

.admin-photo-grid {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-bottom: 12px;
}

.admin-photo-item {
  position: relative;
  width: 104px;
  overflow: hidden;
  border: 1px solid var(--line);
  background: #171719;
}

.admin-photo-item.is-main-image {
  border-color: #009246;
  box-shadow: 0 0 0 1px #ce2b37;
}

.admin-photo-select {
  display: grid;
  width: 100%;
  min-height: 92px;
  grid-template-rows: 66px auto;
  gap: 5px;
  padding: 4px;
  border: 0;
  background: transparent;
  color: var(--muted);
  cursor: pointer;
  text-align: left;
}

.admin-photo-select > .admin-photo-preview-image {
  display: block;
  width: 100%;
  height: 66px;
}

.admin-photo-select > span:not(.admin-photo-preview-image) {
  overflow: hidden;
  font-size: 10px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.admin-photo-item.is-main-image .admin-photo-select > span:not(.admin-photo-preview-image) {
  color: #b9f1d2;
  font-weight: 700;
}

.admin-photo-remove {
  position: absolute;
  top: 5px;
  right: 5px;
  display: grid;
  width: 22px;
  height: 22px;
  place-items: center;
  border: 1px solid rgba(255, 255, 255, .4);
  border-radius: 50%;
  background: rgba(23, 23, 25, .88);
  color: white;
  cursor: pointer;
  font-size: 16px;
  line-height: 1;
}

.admin-photo-remove:hover {
  background: #a3212a;
}

.admin-photo-field input[type='file'] {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
}

.admin-add-photo {
  margin-bottom: 2px;
}

.admin-add-photo:disabled {
  cursor: not-allowed;
  opacity: .5;
}

.admin-vehicle-form > .button {
  margin-top: 8px;
}

.admin-inventory h2 {
  margin-bottom: 16px;
}

.admin-sales {
  margin-bottom: 26px;
  padding: clamp(18px, 3vw, 28px);
  border: 1px solid var(--line);
  border-radius: 12px;
  background: var(--surface);
}

.admin-sales-list {
  display: grid;
  gap: 10px;
}

.admin-sales-list article {
  display: grid;
  grid-template-columns: 62px minmax(0, 1fr) auto;
  align-items: center;
  gap: 12px;
  padding: 12px 0;
  border-top: 1px solid var(--line);
}

.admin-sales-list .admin-sales-image {
  width: 62px;
  height: 49px;
  flex: 0 0 auto;
}

.admin-sales-list article > div {
  display: grid;
  min-width: 0;
  gap: 5px;
}

.admin-sales-list strong {
  overflow: hidden;
  font-size: 12px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.admin-sales-list small,
.admin-sales-list p {
  color: var(--muted);
  font-size: 11px;
  line-height: 1.6;
}

.admin-sales-list p {
  margin: 4px 0 0;
  overflow-wrap: anywhere;
}

.admin-sale-controls {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: end;
  flex: 1 0 100%;
  gap: 8px;
}

.admin-sale-controls label {
  display: grid;
  grid-column: 1 / -1;
  min-width: 0;
  gap: 5px;
  color: var(--muted);
  font-size: 11px;
}

.admin-sale-controls :is(input, select) {
  width: 100%;
  min-width: 0;
  min-height: 34px;
  padding: 6px 8px;
  border: 1px solid var(--line);
  background: #1c1c1f;
  color: var(--text);
  font: inherit;
  font-size: 11px;
}

.admin-sale-controls .custom-select-popover {
  max-width: 100%;
}

.admin-sale-controls .custom-select-option {
  justify-content: flex-start;
  overflow-wrap: anywhere;
  white-space: normal;
}

.admin-sale-controls > small {
  grid-column: 1 / -1;
  color: var(--muted);
  font-size: 11px;
}

.admin-submissions {
  margin-bottom: 26px;
  padding: clamp(18px, 3vw, 28px);
  border: 1px solid color-mix(in srgb, var(--brand-accent-deep) 18%, transparent);
  background: linear-gradient(135deg, #0b1119, #070a0e);
}

.admin-submissions-heading {
  display: flex;
  justify-content: space-between;
  margin-bottom: 16px;
}

.admin-submissions-heading .eyebrow {
  margin-bottom: 8px;
}

.admin-submissions-heading h2 {
  display: flex;
  align-items: center;
  gap: 10px;
  margin: 0;
  font-family: Manrope, sans-serif;
  font-size: 22px;
  font-weight: 600;
  letter-spacing: -.05em;
}

.admin-submissions-heading h2 span {
  display: grid;
  min-width: 24px;
  height: 24px;
  place-items: center;
  border-radius: 20px;
  background: color-mix(in srgb, var(--brand-accent-deep) 12%, transparent);
  color: var(--accent);
  font-size: 12px;
  letter-spacing: 0;
}

.admin-submissions-empty {
  margin: 0;
  padding: 18px 0 4px;
  border-top: 1px solid var(--line);
  color: var(--muted);
  font-size: 13px;
}

.admin-submission-list {
  display: grid;
  gap: 12px;
}

.admin-submission {
  display: grid;
  grid-template-columns: minmax(0, .8fr) minmax(0, 1.2fr);
  gap: 20px;
  padding: 16px 0;
  border-top: 1px solid var(--line);
}

.admin-submission-photos {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(110px, 1fr));
  align-content: start;
  gap: 7px;
}

.admin-submission-photos a {
  display: block;
  height: 92px;
  overflow: hidden;
  border: 1px solid var(--line);
}

.admin-submission-photos img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform .2s ease;
}

.admin-submission-photos a:hover img {
  transform: scale(1.05);
}

.admin-submission-main {
  min-width: 0;
}

.admin-submission-title {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
}

.admin-submission-title h3 {
  margin: 5px 0 0;
  font-family: Manrope, sans-serif;
  font-size: 15px;
  font-weight: 600;
}

.admin-submission-title time {
  flex: 0 0 auto;
  color: var(--muted);
  font-size: 11px;
}

.admin-submission-status {
  display: inline-block;
  padding: 3px 7px;
  border: 1px solid var(--line);
  color: var(--muted);
  font-size: 10px;
  letter-spacing: .06em;
  text-transform: uppercase;
}

.admin-submission-status.status-new {
  border-color: color-mix(in srgb, var(--brand-accent-deep) 36%, transparent);
  color: var(--accent);
}

.admin-submission-status.status-contacted {
  border-color: rgba(255, 207, 100, .35);
  color: #ffcf64;
}

.admin-submission-status.status-closed {
  border-color: rgba(0, 146, 70, .4);
  color: #77dba3;
}

.admin-submission-status.status-reviewing,
.admin-submission-status.status-contacted {
  border-color: rgba(255, 207, 100, .35);
  color: #ffcf64;
}

.admin-submission-status.status-accepted {
  border-color: rgba(0, 146, 70, .5);
  background: rgba(0, 146, 70, .08);
  color: #8be1ad;
}

.admin-submission-status.status-countered {
  border-color: color-mix(in srgb, var(--brand-accent-deep) 40%, transparent);
  background: color-mix(in srgb, var(--brand-accent-deep) 6%, transparent);
  color: var(--accent);
}

.admin-submission-status.status-rejected {
  border-color: rgba(255, 154, 145, .38);
  color: #ff9a91;
}

.admin-submission-specs,
.admin-submission-description {
  margin: 8px 0 0;
  color: var(--muted);
  font-size: 11px;
  line-height: 1.6;
}

.admin-submission-contact {
  display: flex;
  flex-wrap: wrap;
  gap: 7px 14px;
  margin-top: 10px;
  font-size: 11px;
}

.admin-submission-contact a {
  color: var(--accent);
}

.admin-submission-response {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  align-items: end;
  gap: 10px;
  margin-top: 15px;
  padding-top: 13px;
  border-top: 1px solid var(--line);
}

.admin-submission-response > label {
  display: grid;
  min-width: 0;
  gap: 6px;
  color: var(--muted);
  font-size: 11px;
}

.admin-submission-response > label > span {
  display: grid;
  gap: 4px;
}

.admin-submission-response > label small {
  color: #8793a1;
  font-size: 9px;
  font-weight: 400;
  line-height: 1.4;
}

.admin-response-section-divider {
  display: flex;
  grid-column: 1 / -1;
  align-items: center;
  gap: 10px;
  margin-top: 3px;
  padding-top: 11px;
  border-top: 1px solid rgba(220, 220, 220, .14);
  color: #aab6c3;
  font-size: 10px;
  font-weight: 600;
}

.admin-submission-response select,
.admin-submission-response input,
.admin-submission-response textarea,
.submission-message-form textarea {
  width: 100%;
  min-width: 0;
  padding: 9px;
  border: 1px solid var(--line);
  border-radius: 2px;
  background: #1c1c1f;
  color: var(--text);
  font: inherit;
  font-size: 12px;
}

.admin-submission-response select,
.admin-submission-response input {
  min-height: 36px;
}

.admin-submission-response textarea,
.submission-message-form textarea {
  min-height: 62px;
  resize: vertical;
}

.admin-response-message {
  grid-column: 1 / -1;
}

.admin-submission-response > .admin-delete {
  grid-column: auto;
  justify-self: end;
}

.admin-submission-counter {
  margin: 12px 0 0;
  color: var(--accent);
  font-size: 12px;
}

.submission-conversation {
  display: grid;
  gap: 9px;
  margin-top: 15px;
  padding-top: 12px;
  border-top: 1px solid var(--line);
}

.submission-conversation h4 {
  margin: 0;
  font-family: Manrope, sans-serif;
  font-size: 14px;
  font-weight: 600;
}

.submission-message {
  display: grid;
  justify-self: start;
  max-width: min(100%, 520px);
  gap: 5px;
  padding: 10px 12px;
  border: 1px solid var(--line);
  background: #1a1a1d;
}

.submission-message.from-admin {
  justify-self: end;
  border-color: color-mix(in srgb, var(--brand-accent-deep) 20%, transparent);
  background: color-mix(in srgb, var(--brand-accent-deep) 4.5%, transparent);
}

.submission-message.from-customer {
  border-color: rgba(0, 146, 70, .22);
}

.submission-message > span {
  color: var(--accent);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: .06em;
  text-transform: uppercase;
}

.submission-message p {
  margin: 0;
  color: #d3d9df;
  font-size: 12px;
  line-height: 1.65;
  overflow-wrap: anywhere;
  white-space: pre-wrap;
}

.submission-message time {
  color: var(--muted);
  font-size: 10px;
}

.submission-message-form {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: end;
  gap: 8px;
}

.submission-message-form > .form-error,
.submission-message-form > .form-success {
  grid-column: 1 / -1;
}

.admin-vehicle-row {
  display: grid;
  grid-template-columns: 62px minmax(0, 1fr);
  align-items: center;
  gap: 12px;
  padding: 13px 0;
  border-top: 1px solid var(--line);
}

.admin-vehicle-row > .admin-vehicle-thumbnail {
  display: block;
  width: 62px;
  height: 49px;
  flex: 0 0 auto;
}

.admin-vehicle-row > div {
  display: grid;
  min-width: 0;
  gap: 5px;
}

.admin-vehicle-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  margin-top: 5px;
}

.admin-vehicle-actions .admin-delete {
  grid-column: auto;
  justify-self: auto;
  margin-left: auto;
}

.admin-vehicle-row strong {
  overflow: hidden;
  font-size: 12px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.admin-vehicle-row small {
  color: var(--muted);
  font-size: 10px;
}

.admin-delete {
  grid-column: 2 / -1;
  justify-self: end;
  padding: 4px 0;
  border: 0;
  background: transparent;
  color: #ff9a91;
  cursor: pointer;
  font-size: 11px;
}

.admin-delete:hover {
  color: #fff;
}

.admin-access-denied {
  display: flex;
  min-height: calc(100vh - 235px);
  align-items: center;
  justify-content: center;
  padding: 32px 0;
}

.admin-access-card {
  --admin-access-accent: #8be0ad;
  position: relative;
  width: min(100%, 620px);
  overflow: hidden;
  padding: clamp(26px, 5vw, 48px);
  border: 1px solid rgba(180, 214, 193, .18);
  border-radius: 16px;
  background: linear-gradient(145deg, #111714, #0b0e0c 72%);
  box-shadow: 0 24px 70px rgba(0, 0, 0, .35), inset 0 1px rgba(255, 255, 255, .035);
}

.site-shell[data-theme="admin"] .admin-access-card {
  --admin-access-accent: #8be0ad;
  border-color: rgba(180, 214, 193, .18);
  background: linear-gradient(145deg, #111714, #0b0e0c 72%);
  box-shadow: 0 22px 58px rgba(0, 0, 0, .3), inset 0 1px rgba(255, 255, 255, .035);
}

.admin-access-icon {
  display: grid;
  width: 58px;
  height: 58px;
  place-items: center;
  margin-bottom: 24px;
  border: 1px solid rgba(139, 224, 173, .24);
  border-radius: 16px;
  background: rgba(139, 224, 173, .08);
  color: #8be0ad;
}

.site-shell[data-theme="admin"] .admin-access-icon {
  border-color: rgba(139, 224, 173, .24);
  background: rgba(139, 224, 173, .08);
  color: #8be0ad;
}

.admin-access-icon svg {
  width: 28px;
  height: 28px;
}

.admin-access-status {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  margin: 0 0 21px;
  padding: 7px 10px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: color-mix(in srgb, var(--surface) 72%, transparent);
  color: var(--muted);
  font-size: 11px;
  font-weight: 600;
  letter-spacing: .04em;
}

.admin-access-status span {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: #8be0ad;
  box-shadow: 0 0 10px rgba(139, 224, 173, .35);
}

.site-shell[data-theme="admin"] .admin-access-status {
  border-color: rgba(180, 214, 193, .18);
  background: rgba(255, 255, 255, .025);
  color: #bfd0c5;
}

.site-shell[data-theme="admin"] .admin-access-status span {
  background: #8be0ad;
  box-shadow: 0 0 10px rgba(139, 224, 173, .35);
}

.admin-access-card .eyebrow {
  margin: 0;
  color: #8be0ad;
}

.site-shell[data-theme="admin"] .admin-access-card .eyebrow,
.site-shell[data-theme="admin"] .admin-access-card h1 em {
  color: #8be0ad;
}

.admin-access-card h1 {
  margin: 10px 0 12px;
  font-family: Manrope, sans-serif;
  font-size: clamp(32px, 5vw, 48px);
  font-weight: 600;
  letter-spacing: -.06em;
  line-height: 1.12;
}

.admin-access-card h1 em {
  color: #8be0ad;
  font-weight: 500;
}

.admin-access-description {
  max-width: 470px;
  margin: 0;
  color: var(--muted);
  font-size: 14px;
  line-height: 1.75;
}

.admin-access-account-note {
  margin: 20px 0 0;
  padding: 12px 14px;
  border: 1px solid rgba(255, 160, 110, .28);
  border-radius: 8px;
  background: rgba(255, 160, 110, .07);
  color: #ffc29f;
  font-size: 12px;
  line-height: 1.6;
}

.admin-access-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  margin-top: 26px;
}

.admin-access-denied .button {
  min-height: 46px;
}

.admin-access-actions .button-accent {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
}

.admin-access-actions .button-accent {
  border-color: #8be0ad;
  background: #8be0ad;
  color: #101612;
}

.admin-access-actions .button-accent:hover {
  border-color: #a4eabd;
  background: #a4eabd;
}

.site-shell[data-theme="admin"] .admin-access-actions .button-accent {
  border-color: #8be0ad;
  background: #8be0ad;
  color: #101612;
}

.site-shell[data-theme="admin"] .admin-access-actions .button-accent:hover {
  border-color: #a4eabd;
  background: #a4eabd;
}

.admin-access-footnote {
  margin: 24px 0 0;
  padding-top: 17px;
  border-top: 1px solid var(--line);
  color: var(--muted);
  font-size: 11px;
}

.services-section {
  padding: 104px 0 112px;
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
  background: #1c1c1f;
}

.service-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 15px;
  margin-top: 45px;
}

.service-card {
  position: relative;
  min-height: 239px;
  padding: 25px 24px;
  border: 1px solid var(--line);
  background: rgba(255, 255, 255, .015);
}

.service-number {
  color: var(--muted);
  font-size: 11px;
  letter-spacing: .1em;
}

.service-symbol {
  position: absolute;
  top: 18px;
  right: 22px;
  color: var(--accent);
  font-size: 24px;
}

.service-card h3 {
  margin: 37px 0 10px;
  font-family: Manrope, sans-serif;
  font-size: 18px;
  font-weight: 600;
  letter-spacing: -.04em;
}

.service-card p {
  min-height: 46px;
  margin: 0 0 18px;
  color: var(--muted);
  font-size: 12px;
  line-height: 1.7;
}

.sell-section {
  display: grid;
  grid-template-columns: minmax(240px, .75fr) minmax(0, 1.25fr);
  gap: clamp(24px, 4vw, 54px);
  align-items: start;
  margin-top: 96px;
  margin-bottom: 96px;
  padding: clamp(22px, 3.5vw, 42px);
  border: 1px solid color-mix(in srgb, var(--brand-accent-deep) 18%, transparent);
  background:
    radial-gradient(ellipse at 5% 0%, color-mix(in srgb, var(--brand-accent-deep) 10%, transparent), transparent 50%),
    linear-gradient(145deg, #0b1119, #171719 75%);
  scroll-margin-top: 110px;
}

.sell-section-heading {
  position: sticky;
  top: 125px;
}

.sell-section-heading h2 {
  margin: 17px 0 16px;
  font-family: Manrope, sans-serif;
  font-size: clamp(34px, 4.1vw, 52px);
  font-weight: 600;
  letter-spacing: -.065em;
  line-height: 1.08;
}

.sell-section-heading h2 em {
  color: var(--accent);
  font-weight: 500;
}

.sell-section-heading > p:not(.eyebrow) {
  max-width: 440px;
  margin: 0;
  color: var(--muted);
  font-size: 13px;
  line-height: 1.8;
}

.sell-form {
  min-width: 0;
  padding: clamp(18px, 2.5vw, 28px);
  border: 1px solid var(--line);
  background: rgba(23, 23, 25, .72);
}

.sell-form-heading,
.sell-upload-heading,
.sell-form-submit {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 15px;
}

.sell-form-heading {
  margin-bottom: 20px;
  padding-bottom: 15px;
  border-bottom: 1px solid var(--line);
}

.sell-form-heading > div > span {
  color: var(--accent);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: .16em;
}

.sell-form-heading h3 {
  margin: 6px 0 0;
  font-family: Manrope, sans-serif;
  font-size: 17px;
  font-weight: 600;
}

.sell-form-private {
  color: #aab5c2;
  font-size: 10px;
  text-align: right;
}

.sell-form-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.sell-form label {
  display: grid;
  min-width: 0;
  gap: 6px;
  color: var(--muted);
  font-size: 12px;
}

.sell-form input,
.sell-form textarea {
  width: 100%;
  min-width: 0;
  min-height: 40px;
  padding: 10px 11px;
  border: 1px solid var(--line);
  border-radius: 2px;
  outline: 0;
  background: #1a1a1d;
  color: var(--text);
  font: inherit;
  font-size: 12px;
  transition: border-color .2s ease;
}

.sell-form input:focus,
.sell-form textarea:focus {
  border-color: color-mix(in srgb, var(--brand-accent-deep) 72%, transparent);
}

.sell-form input::placeholder,
.sell-form textarea::placeholder {
  color: #687584;
}

.sell-form .sell-form-description {
  margin-top: 13px;
}

.sell-form textarea {
  resize: vertical;
}

.sell-upload {
  margin-top: 17px;
}

.sell-upload-heading {
  margin-bottom: 10px;
}

.sell-upload-heading > div {
  display: grid;
  gap: 4px;
}

.sell-upload-heading strong {
  color: #dce5ee;
  font-size: 12px;
}

.sell-upload-heading span {
  color: var(--muted);
  font-size: 10px;
}

.sell-photo-grid {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.sell-photo-preview {
  position: relative;
  width: 86px;
  height: 66px;
  overflow: hidden;
  border: 1px solid var(--line);
  background: #171719;
}

.sell-photo-preview img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.sell-photo-preview button {
  position: absolute;
  top: 3px;
  right: 3px;
