  background: rgba(23, 23, 25, .88);
  color: white;
  cursor: pointer;
  font-size: 15px;
  line-height: 1;
}

.sell-upload-drop {
  display: grid;
  width: 100%;
  min-height: 100px;
  place-content: center;
  gap: 5px;
  border: 1px dashed color-mix(in srgb, var(--brand-accent-deep) 32%, transparent);
  background: color-mix(in srgb, var(--brand-accent-deep) 2.5%, transparent);
  color: #c9d5e0;
  cursor: pointer;
  text-align: center;
}

.sell-upload-drop:hover {
  border-color: var(--accent);
  background: color-mix(in srgb, var(--brand-accent-deep) 6%, transparent);
}

.sell-upload-drop > span {
  color: var(--accent);
  font-size: 22px;
}

.sell-upload-drop strong {
  font-size: 12px;
}

.sell-upload-drop small {
  color: var(--muted);
  font-size: 10px;
}

.sell-form-submit {
  align-items: flex-end;
  margin-top: 18px;
  padding-top: 15px;
  border-top: 1px solid var(--line);
}

.sell-form-submit p {
  max-width: 250px;
  margin: 0;
  color: var(--muted);
  font-size: 10px;
  line-height: 1.7;
}

.sell-form-submit .button {
  flex: 0 0 auto;
  gap: 15px;
}

.about-section {
  display: grid;
  grid-template-columns: 1.06fr .94fr;
  align-items: center;
  gap: 9%;
  padding-top: 123px;
  padding-bottom: 123px;
}

.about-visual {
  display: grid;
  gap: 18px;
}

.about-section-logo {
  display: block;
  width: 92%;
  height: auto;
  justify-self: center;
}

.about-image {
  position: relative;
  height: 430px;
  background: var(--surface);
}

.about-image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  filter: saturate(.72);
}

.image-stamp {
  position: absolute;
  right: -24px;
  bottom: 24px;
  display: grid;
  width: 90px;
  height: 90px;
  align-content: center;
  border-radius: 50%;
  background: var(--accent);
  color: var(--accent-ink);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: .08em;
  line-height: 1.3;
  text-align: center;
  transform: rotate(9deg);
}

.about-copy h2 {
  margin-bottom: 24px;
}

.about-copy > p:not(.eyebrow) {
  margin: 0 0 15px;
  color: var(--muted);
  font-size: 13px;
  line-height: 1.9;
}

.about-copy .text-link {
  margin-top: 12px;
}

.contact-section {
  display: grid;
  grid-template-columns: .9fr 1.1fr;
  gap: 12%;
  padding-top: 77px;
  padding-bottom: 95px;
  border-top: 1px solid var(--line);
}

.dedicated-contact-page {
  padding-top: 1px;
}

.dedicated-contact-page .contact-section {
  padding-top: 150px;
}

.contact-copy :is(h1, h2) {
  margin: 24px 0 0;
  font-family: Manrope, sans-serif;
  font-size: clamp(42px, 5vw, 64px);
  font-weight: 600;
  letter-spacing: -.075em;
  line-height: 1.02;
}

.contact-copy :is(h1, h2) em {
  color: var(--accent);
  font-weight: 500;
}

.location-section {
  padding: 0 0 105px;
}

.location-heading {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 20px;
  margin-bottom: 22px;
}

.location-heading h2 {
  margin: 13px 0 0;
  font-family: Manrope, sans-serif;
  font-size: clamp(29px, 4vw, 43px);
  font-weight: 600;
  letter-spacing: -.06em;
}

.location-heading h2 em {
  color: var(--accent);
  font-weight: 500;
}

.location-map {
  height: clamp(260px, 38vw, 440px);
  overflow: hidden;
  border: 1px solid var(--line);
  background: var(--surface);
}

.location-map iframe {
  width: 100%;
  height: 100%;
  border: 0;
  filter: grayscale(.85) invert(.9) contrast(.82) hue-rotate(175deg);
}

.cookie-map-placeholder {
  display: grid;
  width: 100%;
  height: 100%;
  align-content: center;
  justify-items: center;
  gap: 14px;
  padding: 24px;
  background:
    radial-gradient(ellipse at 50% 40%, rgba(119, 17, 31, .2), transparent 60%),
    var(--surface);
  text-align: center;
}

.cookie-map-placeholder p {
  max-width: 430px;
  margin: 0;
  color: var(--muted);
  font-size: 13px;
  line-height: 1.6;
}

.cookie-map-placeholder button {
  min-height: 40px;
  padding: 0 16px;
  border: 1px solid rgba(255, 255, 255, .16);
  border-radius: 8px;
  background: #303030;
  color: #fff;
  cursor: pointer;
  font: inherit;
  font-size: 12px;
  font-weight: 700;
}

.cookie-consent-banner {
  position: fixed;
  z-index: 120;
  right: 16px;
  bottom: 16px;
  left: 16px;
  display: flex;
  max-height: min(80vh, 760px);
  flex-wrap: wrap;
  align-items: center;
  gap: 18px 28px;
  width: min(1040px, calc(100% - 32px));
  overflow-y: auto;
  margin-inline: auto;
  padding: 22px 24px;
  border: 1px solid rgba(198, 55, 68, .3);
  border-radius: 14px;
  background: rgba(11, 10, 12, .97);
  box-shadow: 0 18px 60px rgba(0, 0, 0, .62), 0 0 36px rgba(131, 9, 25, .24);
  color: var(--text);
  -webkit-backdrop-filter: blur(18px);
  backdrop-filter: blur(18px);
}

.cookie-consent-copy {
  flex: 1 1 430px;
}

.cookie-consent-copy .eyebrow {
  margin: 0 0 6px;
  color: #aeb8c7;
  font-size: 9px;
  letter-spacing: .14em;
}

.cookie-consent-copy h2 {
  margin: 0 0 7px;
  font-family: Manrope, sans-serif;
  font-size: 19px;
  font-weight: 650;
  letter-spacing: -.03em;
}

.cookie-consent-copy > p:last-child {
  max-width: 650px;
  margin: 0;
  color: var(--muted);
  font-size: 12px;
  line-height: 1.55;
}

.cookie-consent-actions {
  display: flex;
  flex: 1 1 360px;
  flex-wrap: wrap;
  align-items: center;
  justify-content: flex-end;
  gap: 9px;
}

.cookie-consent-actions button,
.cookie-consent-save {
  min-height: 40px;
  padding: 0 14px;
  border: 1px solid rgba(255, 255, 255, .16);
  border-radius: 8px;
  background: rgba(255, 255, 255, .045);
  color: #f3eeee;
  cursor: pointer;
  font: inherit;
  font-size: 11px;
  font-weight: 650;
}

.cookie-consent-actions button:hover,
.cookie-consent-save:hover {
  border-color: rgba(255, 255, 255, .28);
}

.cookie-consent-actions .cookie-consent-primary,
.cookie-consent-save {
  border-color: rgba(255, 255, 255, .16);
  background: #303030;
  color: #fff;
}

.cookie-preference-options {
  display: grid;
  flex: 1 0 100%;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 9px;
}

.cookie-preference-option {
  display: flex;
  min-width: 0;
  align-items: flex-start;
  gap: 9px;
  padding: 12px;
  border: 1px solid rgba(255, 255, 255, .1);
  border-radius: 9px;
  background: rgba(255, 255, 255, .025);
  cursor: pointer;
}

.cookie-preference-option input {
  flex: 0 0 auto;
  margin: 3px 0 0;
  accent-color: #c33749;
}

.cookie-preference-option > span:nth-of-type(1) {
  display: grid;
  gap: 4px;
}

.cookie-preference-option strong {
  color: #f3eeee;
  font-size: 11px;
}

.cookie-preference-option small {
  color: var(--muted);
  font-size: 10px;
  line-height: 1.45;
}

.cookie-preference-required {
  flex: 0 0 auto;
  margin-left: auto;
  color: #d78a91;
  font-size: 9px;
  text-align: right;
}

.cookie-preference-options .cookie-consent-save {
  justify-self: end;
}

.cookie-consent-error {
  flex: 1 1 100%;
  margin: 0;
  color: #ff9a9f;
  font-size: 11px;
}

.cookie-settings-trigger {
  position: fixed;
  z-index: 119;
  bottom: 18px;
  left: 18px;
  min-height: 36px;
  padding: 0 12px;
  border: 1px solid rgba(198, 55, 68, .32);
  border-radius: 999px;
  background: rgba(11, 10, 12, .92);
  box-shadow: 0 6px 22px rgba(0, 0, 0, .35);
  color: #e8cfd1;
  cursor: pointer;
  font: inherit;
  font-size: 10px;
  -webkit-backdrop-filter: blur(12px);
  backdrop-filter: blur(12px);
}

.cookie-settings-trigger:hover {
  border-color: rgba(218, 73, 87, .7);
}

@media (max-width: 680px) {
  .catalog-header-filter {
    margin-right: 8px;
  }

  .menu-backdrop {
    width: 100vw;
    height: 100dvh;
  }

  .menu-drawer {
    width: 100vw !important;
    border-right: 0 !important;
    border-radius: 0 !important;
    box-shadow: none !important;
  }

  .cookie-consent-banner {
    right: 10px;
    bottom: 10px;
    left: 10px;
    gap: 14px;
    width: calc(100% - 20px);
    max-height: min(78dvh, 700px);
    padding: 17px;
  }

  .cookie-consent-copy {
    flex-basis: 100%;
  }

  .cookie-consent-copy h2 {
    font-size: 17px;
  }

  .cookie-consent-actions {
    flex-basis: 100%;
    justify-content: stretch;
    gap: 7px;
  }

  .cookie-consent-actions button {
    min-width: 0;
    flex: 1 1 auto;
    padding-inline: 9px;
    font-size: 10px;
  }

  .cookie-preference-options {
    grid-template-columns: 1fr;
  }

  .cookie-settings-trigger {
    bottom: 12px;
    left: 12px;
  }
}

.reviews-section {
  padding-top: 8px;
  padding-bottom: 105px;
  border-top: 1px solid var(--line);
}

.reviews-heading {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 20px;
  margin-bottom: 22px;
}

.reviews-heading h2 {
  margin: 13px 0 0;
  font-family: Manrope, sans-serif;
  font-size: clamp(29px, 4vw, 43px);
  font-weight: 600;
  letter-spacing: -.06em;
}

.reviews-heading h2 em {
  color: var(--accent);
  font-weight: 500;
}

.customer-reviews-grid {
  display: flex;
  flex-wrap: nowrap;
  overflow-x: auto;
  overflow-y: hidden;
  gap: 12px;
  padding: 38px 0 42px;
  scroll-snap-type: x mandatory;
  scroll-padding-inline: 0;
  scrollbar-width: none;
  -ms-overflow-style: none;
  overscroll-behavior-inline: contain;
}

.customer-review-card {
  display: flex;
  flex: 0 0 calc((100% - 72px) / 7);
  min-width: 0;
  flex-direction: column;
  padding: 17px;
  scroll-snap-align: start;
  border: 1px solid var(--line);
  background: var(--surface);
}

.review-skeleton {
  display: grid;
  flex: 0 0 calc((100% - 72px) / 7);
  scroll-snap-align: start;
  min-height: 205px;
  align-content: start;
  gap: 16px;
  padding: 19px;
  border: 1px solid var(--line);
  background: var(--surface);
}

.skeleton-line-rating {
  width: 34%;
  height: 20px;
}

.skeleton-line-review {
  width: 100%;
}

.skeleton-line-review-short {
  width: 63%;
}

.skeleton-line-author {
  width: 46%;
  height: 12px;
  margin-top: auto;
}

.customer-review-rating {
  display: flex;
  align-items: center;
  gap: 5px;
  min-height: 30px;
  filter: drop-shadow(0 2px 6px rgba(255, 190, 62, .18));
}

.customer-review-rating span {
  color: #4a4337;
  font-size: 24px;
  line-height: 1;
  transition: transform .2s ease, color .2s ease, text-shadow .2s ease;
}

.customer-review-card:hover .customer-review-rating span.is-filled {
  transform: translateY(-2px);
}

.customer-review-rating span.is-filled {
  color: #fbbc04;
  text-shadow: 0 0 11px rgba(251, 188, 4, .45);
}

.customer-review-card > p {
  flex: 1;
  margin: 12px 0 17px;
  color: #d3d9df;
  font-size: 12px;
  line-height: 1.8;
  overflow-wrap: anywhere;
}

.customer-review-author {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: 8px;
  padding-top: 11px;
  border-top: 1px solid var(--line);
  font-size: 11px;
}

.customer-review-author > span {
  overflow: hidden;
  color: var(--text);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.customer-review-author time {
  flex: 0 0 auto;
  margin-left: auto;
  color: var(--muted);
  font-size: 10px;
}

.customer-review-vehicle {
  margin-top: 11px;
  color: var(--accent);
  font-size: 11px;
}

.customer-review-car-image {
  width: calc(100% + 34px);
  max-width: none;
  height: clamp(150px, 16vw, 205px);
