  object-fit: cover;
  border-top: 1px solid var(--line);
}

.reviews-status {
  margin: 0;
  padding: 18px;
  border: 1px solid var(--line);
  color: var(--muted);
  font-size: 12px;
  line-height: 1.7;
}

.reviews-status a {
  color: var(--accent);
}

.reviews-intro {
  max-width: 760px;
  margin: -5px auto 20px;
  color: var(--muted);
  font-size: 12px;
  line-height: 1.7;
  text-align: center;
}

.reviews-login-link {
  border: 0;
  background: transparent;
  font: inherit;
}

.customer-purchases {
  display: grid;
