.customer-purchases-heading > p:last-child,
.customer-purchases-empty {
  margin: 0;
  color: var(--muted);
  font-size: 12px;
  line-height: 1.7;
}

.customer-purchase {
  display: grid;
  grid-template-columns: minmax(110px, 180px) minmax(0, 1fr);
  gap: 17px;
  padding-top: 15px;
  border-top: 1px solid var(--line);
}

.customer-purchase > .customer-purchase-image {
  width: 100%;
  height: 120px;
}

.customer-purchase-info {
  display: grid;
  align-content: start;
  gap: 8px;
}

.customer-purchase-info h4 {
  margin: 0;
  font-family: Manrope, sans-serif;
  font-size: 15px;
}

.customer-purchase-info > small {
  color: var(--muted);
  font-size: 11px;
}

.customer-review-complete {
  margin: 0;
  color: #b6e8cd;
  font-size: 12px;
}

.customer-review-form {
  display: grid;
  gap: 10px;
}

.customer-review-form > label:not(.review-name-consent) {
  display: grid;
  gap: 6px;
  color: var(--muted);
  font-size: 11px;
}

.customer-review-form select,
.customer-review-form textarea {
  width: 100%;
  min-height: 38px;
  padding: 9px;
  border: 1px solid var(--line);
  border-radius: 2px;
  background: #1c1c1f;
  color: var(--text);
  font: inherit;
  font-size: 12px;
}

.customer-review-form textarea {
  min-height: 75px;
