.review-name-consent {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  color: var(--muted);
  font-size: 11px;
  line-height: 1.5;
}

.review-name-consent input {
  flex: 0 0 auto;
  margin: 1px 0 0;
  accent-color: var(--accent);
}

.customer-review-form .button {
  justify-self: start;
}

.customer-requests {
  padding-top: 40px;
  padding-bottom: 100px;
  border-top: 1px solid var(--line);
}

.customer-requests-list {
  display: grid;
  gap: 15px;
  margin-top: 25px;
}

.customer-request {
  padding: clamp(16px, 3vw, 23px);
  border: 1px solid var(--line);
  background: var(--surface);
}

.customer-request-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 15px;
