.customer-request-header h3 {
  margin: 8px 0 0;
  font-family: Manrope, sans-serif;
  font-size: 17px;
  font-weight: 600;
}

.customer-request-header time {
  flex: 0 0 auto;
  color: var(--muted);
  font-size: 11px;
}

.customer-request-images {
  display: flex;
  min-width: 0;
  max-width: 100%;
  flex: 1 1 auto;
  overflow-x: auto;
  overflow-y: hidden;
  overscroll-behavior-x: contain;
  scroll-snap-type: x mandatory;
  scrollbar-color: color-mix(in srgb, var(--brand-accent-deep) 55%, transparent) rgba(255, 255, 255, .06);
