  overflow-wrap: anywhere;
}

.contact-form #contact-email-error {
  margin-top: -3px;
}

.contact-form input[aria-invalid="true"] {
  border-color: #ff9a91;
}

.vehicle-detail-link {
  display: block;
}

.vehicle-title-row h3 a {
  transition: color .2s ease;
}

.vehicle-title-row h3 a:hover {
  color: var(--accent);
}

.site-footer {
  padding: 58px max(7.3%, calc((100% - 1120px) / 2)) 20px;
  border-top: 1px solid var(--line);
  background:
    #09090b;
}

.footer-main {
  display: grid;
  grid-template-columns: minmax(190px, 1.15fr) minmax(110px, .7fr) minmax(125px, .75fr) minmax(300px, 1.8fr);
  gap: clamp(24px, 3.2vw, 46px);
  padding-bottom: 48px;
}

.brand-footer {
  font-size: 21px;
}

.brand-footer .italian-flag {
  width: 23px;
  height: 15px;
  margin-left: 5px;
}

.footer-tagline {
  margin: 18px 0 9px;
  color: var(--text);
  font-size: 14px;
  font-weight: 600;
}

.footer-history {
  max-width: 285px;
  margin: 0;
  color: var(--muted);
  font-size: 12px;
  line-height: 1.8;
}

.footer-primary-link {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  margin-top: 21px;
  padding: 10px 12px;
  border: 1px solid color-mix(in srgb, var(--brand-accent-deep) 30%, transparent);
  background: color-mix(in srgb, var(--brand-accent-deep) 7%, transparent);
  color: var(--accent);
  cursor: pointer;
  font-size: 11px;
  font-weight: 700;
  transition: background .2s ease, border-color .2s ease;
}

.footer-primary-link:hover {
  border-color: var(--accent);
  background: color-mix(in srgb, var(--brand-accent-deep) 14%, transparent);
}

.footer-social-links {
  display: flex;
  flex-wrap: wrap;
  gap: 9px;
  margin-top: 20px;
}

.footer-social-link {
  display: inline-flex;
  min-height: 36px;
  align-items: center;
  gap: 8px;
  padding: 0 11px;
  border: 1px solid rgba(220, 220, 220, .12);
  border-radius: 999px;
  background: rgba(255, 255, 255, .025);
  color: #c3ccd6;
  font-size: 10px;
  font-weight: 600;
  text-decoration: none;
  transition: transform .22s ease, border-color .22s ease, background .22s ease, color .22s ease;
}

.footer-social-link .site-icon {
  width: 15px;
  height: 15px;
}

.footer-social-link:hover,
.footer-social-link:focus-visible {
  transform: translateY(-2px);
  border-color: color-mix(in srgb, var(--brand-accent-deep) 40%, transparent);
  background: color-mix(in srgb, var(--brand-accent-deep) 8%, transparent);
  color: var(--text);
}

.footer-social-whatsapp .site-icon,
.footer-whatsapp-contact .site-icon {
  color: #56d68b;
}

.footer-whatsapp-contact:hover,
.footer-whatsapp-contact:focus-visible {
  color: #78e5a5 !important;
}

.whatsapp-floating-link {
  position: fixed;
  z-index: 18;
  right: 22px;
  bottom: 24px;
  display: grid;
  width: 56px;
  min-height: 52px;
  height: 56px;
  place-items: center;
  padding: 0;
  border: 1px solid rgba(255, 255, 255, .18);
  border-radius: 50%;
  background: linear-gradient(145deg, #24c96b, #138b4d);
  box-shadow: 0 10px 28px rgba(0, 0, 0, .35), 0 0 0 0 rgba(37, 211, 102, .3);
  color: #fff;
  text-decoration: none;
  animation: whatsapp-link-arrive .55s .2s cubic-bezier(.2, .75, .25, 1) both, whatsapp-link-pulse 3s 1.2s ease-out infinite;
  transition: transform .25s ease, filter .25s ease, box-shadow .25s ease;
}

.whatsapp-floating-link .site-icon {
  width: 25px;
  height: 25px;
}

.whatsapp-floating-link:hover,
.whatsapp-floating-link:focus-visible {
  transform: translateY(-3px) scale(1.02);
  box-shadow: 0 15px 34px rgba(0, 0, 0, .4), 0 0 0 5px rgba(37, 211, 102, .12);
  color: #fff;
  filter: brightness(1.08);
}

@keyframes whatsapp-link-arrive {
  from {
    opacity: 0;
    transform: translateY(14px) scale(.94);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

@keyframes whatsapp-link-pulse {
  0%, 72%, 100% { box-shadow: 0 10px 28px rgba(0, 0, 0, .35), 0 0 0 0 rgba(37, 211, 102, .24); }
  84% { box-shadow: 0 10px 28px rgba(0, 0, 0, .35), 0 0 0 9px rgba(37, 211, 102, 0); }
}

.footer-column {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 12px;
}

.footer-column h2 {
  margin: 2px 0 8px;
  color: var(--text);
  font-size: 13px;
  font-weight: 700;
}

.footer-column a,
.footer-column button,
.footer-column > span {
  padding: 0;
  border: 0;
  background: none;
  color: var(--muted);
  cursor: pointer;
  font-size: 12px;
  line-height: 1.7;
  text-align: left;
  transition: color .2s ease;
}

.footer-column a:hover,
.footer-column button:hover {
  color: var(--accent);
}

.footer-column > span {
  cursor: default;
}

.footer-contact-column {
  gap: 13px;
}

.footer-contact-person {
  display: grid;
  width: 100%;
  gap: 7px;
  padding: 0 0 12px;
  border-bottom: 1px solid var(--line);
}

.footer-contact-person > strong {
  color: var(--text);
  font-size: 12px;
  font-weight: 600;
}

.footer-contact-person > strong span {
  display: block;
  margin-top: 3px;
  color: var(--muted);
  font-size: 10px;
  font-weight: 400;
}

.footer-contact-person a {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  overflow-wrap: anywhere;
}

.footer-contact-person .site-icon,
.footer-address .site-icon {
  width: 14px;
  height: 14px;
  flex: 0 0 auto;
  color: var(--accent);
}

.footer-address {
  display: flex;
  width: 100%;
  align-items: flex-start;
  gap: 9px;
  margin-top: 1px;
}

.footer-address > span:nth-child(2) {
  flex: 1;
}

.footer-address strong {
  display: block;
  margin-bottom: 3px;
  color: var(--text);
  font-size: 11px;
  font-weight: 600;
}

.footer-address > span:last-child {
  color: var(--accent);
}

.footer-hours {
  display: grid;
  grid-template-columns: minmax(190px, .75fr) 2fr;
  align-items: center;
  gap: 30px;
  margin-bottom: 20px;
  padding: 22px 24px;
  border: 1px solid color-mix(in srgb, var(--brand-accent-deep) 16%, transparent);
  background:
    radial-gradient(ellipse at 0 0, color-mix(in srgb, var(--brand-accent-deep) 8%, transparent), transparent 50%),
    rgba(255, 255, 255, .018);
}

.footer-hours-heading {
  display: flex;
  align-items: center;
  gap: 13px;
}

.footer-hours-icon {
  display: grid;
  width: 43px;
  height: 43px;
  flex: 0 0 auto;
  place-items: center;
  border: 1px solid color-mix(in srgb, var(--brand-accent-deep) 24%, transparent);
  background: color-mix(in srgb, var(--brand-accent-deep) 8%, transparent);
  color: var(--accent);
}

.footer-hours-icon .site-icon {
  width: 20px;
  height: 20px;
}

.footer-hours-heading .eyebrow {
  margin-bottom: 5px;
  font-size: 8px;
  letter-spacing: .14em;
}

.footer-hours-heading h2 {
  margin: 0;
  color: var(--text);
  font-family: Manrope, sans-serif;
  font-size: 17px;
  font-weight: 600;
  letter-spacing: -.03em;
}

.footer-hours-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 12px;
}

.footer-hours-day {
  display: grid;
  gap: 5px;
  padding-left: 15px;
  border-left: 1px solid var(--line);
  color: var(--muted);
  font-size: 11px;
}

.footer-hours-day strong {
  margin-bottom: 2px;
  color: var(--text);
  font-size: 11px;
  font-weight: 600;
}

.footer-hours-day time {
  color: #dce5ed;
  font-variant-numeric: tabular-nums;
}

.footer-hours-day .footer-hours-closed,
.footer-hours-day.is-closed > span {
  color: #aeb8c3;
}

.footer-purchase-info {
  margin-bottom: 20px;
  padding: 22px 24px;
  border: 1px solid var(--line);
  background: rgba(255, 255, 255, .018);
}

.footer-purchase-info-heading {
  max-width: 640px;
  margin-bottom: 17px;
}

.footer-purchase-info-heading .eyebrow {
  margin-bottom: 7px;
  font-size: 8px;
  letter-spacing: .15em;
}

.footer-purchase-info-heading h2 {
  margin: 0;
  color: var(--text);
  font-family: Manrope, sans-serif;
  font-size: 17px;
  font-weight: 600;
  letter-spacing: -.03em;
}

.footer-purchase-info-heading > p:last-child {
  margin: 6px 0 0;
  color: var(--muted);
  font-size: 11px;
  line-height: 1.65;
}

.footer-purchase-info-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 12px;
}

.footer-purchase-info-grid article {
  padding: 13px;
  border: 1px solid rgba(220, 220, 220, .08);
  background: rgba(23, 23, 25, .28);
}

.footer-purchase-info-grid strong {
  color: var(--text);
  font-size: 11px;
  font-weight: 600;
}

.footer-purchase-info-grid p {
  margin: 7px 0 0;
  color: var(--muted);
  font-size: 10px;
  line-height: 1.7;
}

.footer-business-note {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  padding: 17px 0;
  border-top: 1px solid var(--line);
}

.footer-business-note > div {
  display: grid;
  gap: 4px;
}

.footer-business-note strong {
  color: var(--text);
  font-size: 11px;
  font-weight: 600;
}

.footer-business-note span,
.footer-business-note p {
  margin: 0;
  color: var(--muted);
  font-size: 10px;
  line-height: 1.65;
}

.footer-business-note p {
  max-width: 430px;
  text-align: right;
}

.footer-bottom {
  display: flex;
  min-height: 46px;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  border-top: 1px solid var(--line);
  color: #788493;
  font-size: 11px;
}

.footer-bottom a {
  color: var(--muted);
  transition: color .2s ease;
}

.footer-bottom a:hover {
  color: var(--accent);
}

.modal-backdrop {
  position: fixed;
  z-index: 40;
  inset: 0;
  display: grid;
  overflow-y: auto;
  place-items: center;
  padding: 24px;
  background: rgba(5, 6, 5, .78);
  backdrop-filter: blur(7px);
}

.auth-modal {
  position: relative;
  width: min(100%, 430px);
  padding: 35px 38px 30px;
  border: 1px solid var(--line);
  background: #1c1c1f;
  box-shadow: 0 30px 100px rgba(0, 0, 0, .45);
}

.modal-close {
  position: absolute;
  top: 15px;
  right: 17px;
  width: 32px;
  height: 32px;
  border: 0;
  background: transparent;
  color: var(--muted);
  cursor: pointer;
  font-size: 25px;
}

.modal-brand {
  margin-bottom: 37px;
}

.auth-modal .eyebrow {
  margin-bottom: 11px;
}

.auth-modal h2 {
  margin: 0;
  font-family: Manrope, sans-serif;
  font-size: 27px;
  font-weight: 600;
  letter-spacing: -.055em;
}

.auth-intro {
  margin: 9px 0 24px;
  color: var(--muted);
  font-size: 13px;
}

.auth-form {
  gap: 15px;
}

.auth-form input {
  min-height: 43px;
}

.auth-form label small {
  color: var(--muted);
  font-size: 11px;
  font-weight: 400;
}

.auth-form .form-submit {
  width: 100%;
  margin-top: 4px;
}

.auth-switch {
  margin: 22px 0 0;
  color: var(--muted);
  font-size: 12px;
  text-align: center;
}

.auth-switch button {
  padding: 0;
  border: 0;
  background: transparent;
  color: var(--accent);
  cursor: pointer;
  font-size: inherit;
  font-weight: 600;
}

.visually-hidden {
  position: absolute;
  overflow: hidden;
  width: 1px;
  height: 1px;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  clip-path: inset(50%);
}

@keyframes drawer-in {
  from {
    opacity: .8;
    transform: translateX(-100%);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}

@keyframes rise-in {
  from {
    opacity: 0;
    transform: translateY(14px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes hero-reveal {
  from {
    opacity: .6;
    transform: scale(1.045);
  }
  to {
    opacity: 1;
    transform: scale(1.015);
  }
}

@keyframes backdrop-in {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

@keyframes cart-in {
  from {
    opacity: .8;
    transform: translateX(100%);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}

