  border: 1px solid color-mix(in srgb, var(--brand-accent-deep) 35%, transparent);
  border-radius: 6px;
  background: color-mix(in srgb, var(--brand-accent-deep) 10%, transparent);
  color: var(--accent);
  cursor: pointer;
  font: inherit;
  font-size: 11px;
  font-weight: 700;
  transition: background .2s ease, border-color .2s ease, transform .2s ease;
}

.purchase-request-view-requests:hover,
.purchase-request-view-requests:focus-visible {
  transform: translateY(-1px);
  border-color: var(--accent);
  background: color-mix(in srgb, var(--brand-accent-deep) 17%, transparent);
}

.purchase-request-form input {
  min-height: 42px;
  padding: 9px 11px;
  border: 1px solid var(--line);
  border-radius: 6px;
  background: #1c1c1f;
  color: var(--text);
}

.installment-summary {
  display: grid;
  gap: 5px;
  margin: 0;
  padding: 13px 15px;
  border: 1px solid color-mix(in srgb, var(--brand-accent-deep) 24%, transparent);
  border-radius: 7px;
  background: color-mix(in srgb, var(--brand-accent-deep) 6%, transparent);
  color: var(--muted);
  font-size: 12px;
  line-height: 1.5;
}

.installment-summary strong {
  color: var(--text);
  font-size: 14px;
}

.installment-summary small {
  color: #8793a1;
}

.admin-installment-hint {
  grid-column: 1 / -1;
  margin: -4px 0 0;
  color: var(--muted);
  font-size: 12px;
  line-height: 1.6;
}

.customer-buy-request {
  display: grid;
  grid-template-columns: minmax(150px, 250px) 1fr;
  gap: 18px;
  align-items: center;
}

.customer-buy-request > .customer-buy-request-image {
  width: 100%;
  height: 155px;
  display: block;
  border: 1px solid var(--line);
  border-radius: 8px;
}

.customer-buy-request h3 {
  margin: 9px 0;
  font-family: Manrope, sans-serif;
}

.customer-buy-request p {
  margin: 6px 0;
  color: var(--muted);
  font-size: 13px;
}

.customer-buy-request p strong {
  color: var(--text);
}

.customer-buy-request small {
  display: block;
  margin-top: 12px;
  color: var(--muted);
}

.customer-buy-request-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px 12px;
  margin-top: 14px;
}

.customer-buy-request-actions .form-error {
  flex-basis: 100%;
  margin: 0;
}

.admin-purchase-summary {
  display: flex;
  align-items: center;
  gap: 13px;
  padding: 10px;
  border: 1px solid var(--line);
  background: #1a1a1d;
}

.admin-purchase-summary > .admin-purchase-image {
  width: 120px;
  height: 82px;
  flex: 0 0 auto;
  border-radius: 5px;
  background: #27272a;
  object-fit: cover;
}

.admin-purchase-summary > div {
  display: grid;
  gap: 6px;
}

.admin-purchase-summary span,
.admin-purchase-summary a {
  color: var(--muted);
  font-size: 13px;
}

.admin-purchase-summary a {
  color: var(--accent);
}

.admin-purchase-summary .admin-purchase-phone {
  display: inline-flex;
  width: fit-content;
  align-items: center;
  gap: 7px;
}

.admin-purchase-phone .site-icon {
  width: 14px;
  height: 14px;
  flex: 0 0 auto;
  color: var(--accent);
}

.admin-purchase-requests-page .admin-submissions {
  border-color: color-mix(in srgb, var(--accent) 22%, var(--line));
  background:
    radial-gradient(ellipse at 100% 0, color-mix(in srgb, var(--accent) 8%, transparent), transparent 42%),
    linear-gradient(145deg, var(--surface), #06090d);
}

.admin-purchase-requests-page .customer-requests-list {
  gap: 12px;
}

.admin-purchase-requests-page .admin-purchase-request {
  position: relative;
  display: grid;
  min-width: 0;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 0 18px;
  padding: clamp(14px, 2vw, 20px);
  overflow: hidden;
  border: 1px solid rgba(220, 220, 220, .12);
  border-radius: 12px;
  background: linear-gradient(120deg, rgba(255, 255, 255, .035), rgba(8, 11, 16, .94) 55%);
  box-shadow: inset 0 1px rgba(255, 255, 255, .035), 0 10px 26px rgba(0, 0, 0, .17);
  transition: border-color .2s ease, transform .2s ease, box-shadow .2s ease;
}

.admin-purchase-requests-page .admin-purchase-request:hover {
  transform: translateY(-2px);
  border-color: color-mix(in srgb, var(--accent) 34%, var(--line));
  box-shadow: inset 0 1px rgba(255, 255, 255, .05), 0 14px 30px rgba(0, 0, 0, .24);
}

.admin-purchase-requests-page .customer-request-header {
  grid-column: 1 / -1;
  align-items: center;
  padding-bottom: 12px;
  border-bottom: 1px solid rgba(220, 220, 220, .1);
}

.admin-purchase-requests-page .customer-request-header h3 {
  margin-top: 7px;
  font-size: 17px;
}

.admin-purchase-requests-page .customer-request-header time {
  padding: 6px 9px;
  border: 1px solid rgba(220, 220, 220, .1);
  border-radius: 6px;
  background: rgba(3, 5, 8, .35);
  font-variant-numeric: tabular-nums;
}

.admin-purchase-requests-page .admin-submission-status {
  padding: 4px 8px;
  border-radius: 20px;
  font-size: 9px;
  font-weight: 700;
  letter-spacing: .07em;
}

.admin-purchase-requests-page .admin-purchase-summary {
  grid-column: 1 / -1;
  min-width: 0;
  align-items: stretch;
  gap: 16px;
  margin-top: 13px;
  padding: 0;
  border: 0;
  background: transparent;
}

.admin-purchase-requests-page .admin-purchase-summary > .admin-purchase-image {
  width: 156px;
  height: 108px;
  border: 1px solid rgba(220, 220, 220, .14);
  border-radius: 8px;
  background: #27272a;
}

.admin-purchase-details {
  display: grid;
  min-width: 0;
  flex: 1 1 auto;
  grid-template-columns: minmax(120px, .75fr) minmax(190px, 1.15fr) minmax(170px, 1fr);
  align-items: center;
  gap: 12px 20px;
}

.admin-purchase-customer,
.admin-purchase-contacts,
.admin-purchase-terms {
  display: grid;
  min-width: 0;
  align-content: center;
  gap: 7px;
}

.admin-purchase-detail-label {
  color: var(--muted);
  font-size: 9px !important;
  font-weight: 700;
  letter-spacing: .1em;
}

.admin-purchase-customer > strong {
  overflow: hidden;
  color: var(--text);
  font-size: 15px;
  text-overflow: ellipsis;
}

.admin-purchase-contacts a {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: 8px;
  overflow-wrap: anywhere;
  font-size: 11px;
}

.admin-purchase-contacts .site-icon,
.admin-purchase-terms .site-icon {
  width: 15px;
  height: 15px;
  flex: 0 0 auto;
}

.admin-purchase-terms {
  gap: 8px;
  padding-left: 16px;
  border-left: 1px solid rgba(220, 220, 220, .1);
}

.admin-purchase-price,
.admin-purchase-installment {
  display: flex;
  align-items: center;
  gap: 8px;
  color: var(--muted);
  font-size: 11px !important;
}

.admin-purchase-price b {
  display: block;
  margin-top: 2px;
  color: var(--text);
  font-family: Manrope, sans-serif;
  font-size: 15px;
  font-weight: 700;
}

.admin-purchase-terms .site-icon {
  color: var(--accent);
}

.admin-purchase-vat {
  padding-left: 23px;
  color: var(--muted);
  font-size: 10px !important;
}

.admin-purchase-requests-page .admin-purchase-accept {
  grid-column: 2;
  justify-self: end;
  margin-top: 12px;
  border-radius: 7px;
}

.admin-purchase-requests-page .admin-purchase-request > .form-success,
.admin-purchase-requests-page .admin-purchase-request > .form-error {
  grid-column: 1 / -1;
  margin: 12px 0 0;
}

@media (max-width: 850px) {
  .admin-purchase-details {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 12px 16px;
  }

  .admin-purchase-terms {
    grid-column: 1 / -1;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    padding: 10px 0 0;
    border-top: 1px solid rgba(220, 220, 220, .1);
    border-left: 0;
  }

  .admin-purchase-vat {
    padding-left: 0;
  }
}

@media (max-width: 560px) {
  .admin-purchase-requests-page .admin-purchase-request {
    grid-template-columns: minmax(0, 1fr);
  }

  .admin-purchase-requests-page .customer-request-header {
    align-items: flex-start;
  }

  .admin-purchase-requests-page .customer-request-header h3 {
    font-size: 15px;
  }

  .admin-purchase-requests-page .admin-purchase-summary {
    gap: 11px;
  }

  .admin-purchase-requests-page .admin-purchase-summary > .admin-purchase-image {
    width: 96px;
    height: 84px;
  }

  .admin-purchase-details {
    grid-template-columns: minmax(0, 1fr);
    gap: 9px;
  }

  .admin-purchase-terms {
    grid-column: auto;
    grid-template-columns: minmax(0, 1fr);
  }

  .admin-purchase-requests-page .admin-purchase-accept {
    grid-column: 1;
    justify-self: stretch;
    justify-content: center;
    margin-top: 14px;
  }
}

@media (max-width: 900px) {
  .advanced-filters {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 1100px) {
  .sold-car-card,
  .sold-car-skeleton {
    flex-basis: calc((100% - 40px) / 3);
  }

  .customer-review-card,
  .review-skeleton {
    flex-basis: calc((100% - 24px) / 3);
  }
}

@media (max-width: 600px) {
  .inventory-toolbar {
    align-items: flex-start;
    flex-direction: column;
    margin-top: 30px;
    padding: 14px;
  }

  .advanced-filters {
    grid-template-columns: 1fr;
    padding: 14px;
  }

  .advanced-filters .search-field {
    grid-column: auto;
  }

  .customer-buy-request {
    grid-template-columns: 1fr;
  }

  .customer-buy-request > .customer-buy-request-image {
    height: 190px;
  }

  .admin-purchase-summary {
    align-items: flex-start;
  }

  .admin-purchase-summary > .admin-purchase-image {
    width: 92px;
    height: 72px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .site-shell[data-theme="public"] .catalog-page-section .catalog-sticky-filters .advanced-filters {
    animation: none;
  }

  .site-shell.catalog-page-shell .site-header,
  .site-shell.catalog-page-shell .catalog-sticky-filters {
    transition: none;
  }
}

/* Catalog header is the only search and filter surface. */
.site-shell.catalog-page-shell .site-header {
  gap: 10px;
  height: 78px;
  padding: 0 16px;
  border-bottom: 1px solid rgba(255, 255, 255, .10);
  background: rgba(16, 16, 18, .78);
  -webkit-backdrop-filter: blur(22px) saturate(175%);
  backdrop-filter: blur(22px) saturate(175%);
  box-shadow: 0 10px 28px rgba(0, 0, 0, .32);
}

.site-shell.catalog-page-shell .brand-main,
.site-shell.catalog-page-shell .header-nav {
  display: none;
}

.catalog-header-tools {
  position: absolute;
  left: 50%;
  display: grid;
  width: min(856px, calc(100% - 220px));
  min-width: 0;
  grid-template-columns: minmax(180px, 760px) 86px;
  align-items: center;
  justify-content: center;
  gap: 10px;
  transform: translateX(-50%);
}

.catalog-header-filter {
  margin-right: 12px;
}

.site-shell.catalog-page-shell .header-actions {
  margin-left: 12px;
}

.catalog-header-back,
.catalog-header-filter {
  display: inline-flex;
  height: 44px;
  align-items: center;
  justify-content: center;
  border: 1px solid rgba(255, 255, 255, .12);
  border-radius: 999px;
  background: rgba(21, 21, 23, .68);
  -webkit-backdrop-filter: blur(18px) saturate(150%);
  backdrop-filter: blur(18px) saturate(150%);
  color: #f0f1f3;
  box-shadow: 0 8px 18px rgba(0, 0, 0, .32);
  cursor: pointer;
  transition: background-color .22s ease, border-color .22s ease, transform .22s ease;
}

.catalog-header-back {
  position: absolute;
  left: 16px;
  width: 44px;
  padding: 0;
}

.catalog-header-back:hover,
.catalog-header-filter:hover,
.catalog-header-filter[aria-expanded="true"] {
  border-color: #45454a;
  background: #202023;
}

.catalog-header-filter {
  min-width: 86px;
  gap: 7px;
  padding: 0 12px;
  font-size: 12px;
  font-weight: 700;
}

.catalog-header-search {
  display: grid;
  width: 100%;
  min-width: 0;
  height: 44px;
  grid-template-columns: minmax(0, 1fr) 44px;
  align-items: center;
  border: 1px solid rgba(255, 255, 255, .12);
  border-radius: 999px;
  background: rgba(21, 21, 23, .68);
  -webkit-backdrop-filter: blur(18px) saturate(150%);
  backdrop-filter: blur(18px) saturate(150%);
  box-shadow: 0 8px 18px rgba(0, 0, 0, .32);
  overflow: hidden;
  transition: border-color .22s ease, background-color .22s ease;
}

.catalog-header-search:focus-within {
  border-color: #45454a;
  background: #1b1b1e;
  outline: 0;
}

.catalog-header-search input {
  width: 100%;
  min-width: 0;
  height: 42px;
  margin: 0;
  padding: 0 4px 0 16px;
  border: 0;
  outline: 0;
  background: transparent;
  box-shadow: none;
  color: #f0f1f3;
  font-size: 14px;
  appearance: none;
  -webkit-appearance: none;
}

.catalog-header-search input::placeholder {
  color: rgba(240, 241, 243, .48);
  opacity: 1;
  transition: color .22s ease;
}

.catalog-header-search:focus-within input::placeholder {
  color: rgba(240, 241, 243, .82);
}

.site-shell.catalog-page-shell .catalog-header-search input,
.site-shell.catalog-page-shell .catalog-header-search input:is(:hover, :focus, :focus-visible),
.site-shell.catalog-page-shell .catalog-header-search input:-webkit-autofill,
.site-shell.catalog-page-shell .catalog-header-search input:-webkit-autofill:hover,
.site-shell.catalog-page-shell .catalog-header-search input:-webkit-autofill:focus {
  border: 0 !important;
  border-radius: 0 !important;
  background: transparent !important;
  background-color: transparent !important;
  box-shadow: none !important;
  outline: 0 !important;
  -webkit-text-fill-color: #f0f1f3 !important;
  caret-color: #f0f1f3 !important;
  transition: none !important;
}

.catalog-header-search input::-webkit-search-cancel-button,
.catalog-header-search input::-webkit-search-decoration {
  display: none;
  width: 0;
  height: 0;
  appearance: none;
  -webkit-appearance: none;
}

.catalog-header-search-icon {
  display: grid;
  height: 42px;
  place-items: center;
  border-left: 1px solid #343438;
  color: #b0b1b7;
}

.catalog-header-search-icon .site-icon {
  width: 17px;
  height: 17px;
}

.site-shell.catalog-page-shell .catalog-page-section {
  padding-top: 104px;
  padding-bottom: 72px;
}

.site-shell.catalog-page-shell .catalog-page-section .advanced-filters {
  position: fixed;
  z-index: 32;
  bottom: 0;
  left: 50%;
  width: min(760px, calc(100vw - 32px));
  max-height: min(500px, calc(100vh - 36px));
  margin: 0;
  border: 1px solid #343438;
  border-radius: 0;
  background: #101012;
  box-shadow: 0 -12px 26px rgba(0, 0, 0, .68), 0 16px 28px rgba(0, 0, 0, .72);
  transform: translateX(-50%);
  transform-origin: center bottom;
  animation: catalog-filter-panel-rise .32s cubic-bezier(.22, .82, .22, 1) both;
}

.site-shell.catalog-page-shell .catalog-page-section .advanced-filters[hidden] {
  display: none;
}

@media (max-width: 900px) {
  .catalog-header-tools {
    width: calc(100% - 148px);
    grid-template-columns: minmax(120px, 1fr) 44px;
  }

  .catalog-header-filter {
    min-width: 44px;
    width: 44px;
    padding: 0;
  }

  .catalog-header-filter span {
    display: none;
  }

  .site-shell.catalog-page-shell .header-actions {
