    height: 78px;
    gap: 6px;
    padding: 0 8px;
  }

  .catalog-header-tools {
    width: calc(100% - 128px);
    grid-template-columns: minmax(80px, 1fr) 40px;
    gap: 6px;
  }

  .catalog-header-back {
