  }

  .catalog-header-search input {
    height: 38px;
    padding-left: 12px;
    font-size: 12px;
  }

  .catalog-header-search-icon {
    height: 38px;
  }

  .site-shell.catalog-page-shell .header-actions {
    gap: 4px;
  }

  .site-shell.catalog-page-shell .header-actions .cart-toggle,
  .site-shell.catalog-page-shell .header-actions .header-account-link {
    display: none;
  }

  .site-shell.catalog-page-shell .catalog-page-section {
    padding-top: 94px;
    padding-bottom: 56px;
  }

  .site-shell.catalog-page-shell .catalog-page-section .advanced-filters {
    bottom: 0;
    width: 100vw;
  }
}

@media (max-width: 680px) {
  .popular-brands {
    padding-top: 30px;
    padding-bottom: 36px;
  }

  .popular-brands-heading {
    align-items: flex-start;
    flex-direction: column;
    gap: 12px;
  }

  .popular-brands-actions {
    width: 100%;
    align-items: flex-start;
    flex-direction: row;
    justify-content: space-between;
  }

  .popular-brands-copy > p:last-child {
    max-width: 100%;
  }

  .popular-brands-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
