  }

  .popular-brand-card {
    min-height: 122px;
    padding: 12px 8px;
  }

  .popular-brand-emblem {
    width: 94px;
    height: 76px;
  }

  .popular-brand-card-chrysler .popular-brand-emblem {
    width: 118px;
    height: 82px;
  }

  .popular-brand-name {
    font-size: 13px;
  }

  .popular-brand-availability {
    font-size: 10px;
  }

  .popular-brand-skeleton {
    min-height: 0;
  }

  .popular-brand-skeleton-card {
    min-height: 122px;
  }

  .popular-brand-skeleton .popular-brand-emblem {
    width: 42px;
    height: 42px;
    padding: 0;
  }

  .popular-brands-empty {
    align-items: flex-start;
    flex-direction: column;
  }

  .site-shell[data-theme="public"] main > .popular-brands {
    padding-block: 36px;
  }

}

.site-shell {
  min-height: 100vh;
  background-color: var(--page);
  background-image: radial-gradient(ellipse at 82% 0, color-mix(in srgb, var(--brand-accent-deep) 5.5%, transparent), transparent 38%);
  transition: background-color .35s ease;
}

.site-shell[data-theme="admin"] {
  --page: #090507;
  --surface: #10090c;
  --surface-raised: #190d11;
  --text: #fff3f4;
  --muted: #b69da1;
  --line: rgba(255, 190, 197, .15);
  --accent: #f06b77;
  --accent-ink: #21070b;
  background-image:
    radial-gradient(ellipse at 82% 0, rgba(168, 24, 45, .2), transparent 42%),
    radial-gradient(ellipse at 0 42%, rgba(108, 13, 30, .1), transparent 35%);
}

.site-shell a,
.site-shell button,
.site-shell input,
.site-shell select,
.site-shell textarea {
  transition-duration: .25s;
}

.site-shell .button {
  border-radius: 7px;
  box-shadow: 0 5px 16px rgba(0, 0, 0, .18);
}

.site-shell .button-accent:hover:not(:disabled) {
  filter: brightness(1.08);
  box-shadow: 0 9px 24px color-mix(in srgb, var(--accent) 25%, transparent);
}

.site-shell .vehicle-card,
.site-shell .service-card,
.site-shell .customer-review-card,
.site-shell .admin-vehicle-form,
.site-shell .admin-inventory,
.site-shell .admin-submission,
.site-shell .admin-sales-list article,
.site-shell .sell-form,
.site-shell .contact-form {
  border-radius: 12px;
  box-shadow: 0 14px 36px rgba(0, 0, 0, .18), inset 0 1px rgba(255, 255, 255, .025);
  transition: border-color .25s ease, box-shadow .25s ease, transform .25s ease;
}

.site-shell .vehicle-card:hover,
.site-shell .service-card:hover,
.site-shell .customer-review-card:hover {
  transform: translateY(-5px);
  box-shadow: 0 22px 46px rgba(0, 0, 0, .28);
}

.site-shell .admin-vehicle-form,
.site-shell .admin-inventory,
.site-shell .admin-submission,
.site-shell .admin-sales-list article {
  border-color: var(--line);
  background-color: color-mix(in srgb, var(--surface) 88%, white 2%);
}

.site-shell :is(input:not([type="checkbox"]):not([type="radio"]), select, textarea) {
  border-radius: 7px;
  transition: border-color .2s ease, box-shadow .2s ease, background-color .2s ease;
}

.site-shell :is(input, select, textarea):focus-visible {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--accent) 20%, transparent);
}

.site-shell[data-theme="admin"] .site-header {
  border-bottom-color: rgba(255, 148, 160, .2);
