.most-viewed-overlay {
  position: fixed;
  z-index: 80;
  inset: 0;
  display: grid;
  overflow-y: auto;
  place-items: center;
  padding: clamp(14px, 3vw, 38px);
}

.most-viewed-backdrop {
  position: fixed;
  inset: 0;
  width: 100%;
  height: 100%;
  border: 0;
  background: rgba(0, 0, 0, .94);
  -webkit-backdrop-filter: blur(3px);
  backdrop-filter: blur(3px);
  cursor: default;
}

.most-viewed-dialog {
  --accent: #aeb8c7;
  --accent-ink: #190609;
  position: relative;
  width: min(1000px, 100%);
  max-height: min(850px, calc(100dvh - 48px));
  overflow-y: auto;
  padding: clamp(21px, 3.2vw, 38px);
  border: 0;
  border-radius: 18px;
  background: transparent;
  box-shadow: none;
}

.most-viewed-heading {
  position: relative;
  display: flex;
  justify-content: center;
  margin-bottom: 38px;
}

.most-viewed-intro {
  position: relative;
  display: flex;
  min-width: 0;
  max-width: 650px;
  flex-direction: column;
  align-items: center;
  gap: 12px;
  text-align: center;
}

.most-viewed-intro::before {
  content: none;
}

.most-viewed-intro > * {
  position: relative;
}

.most-viewed-trophy {
  display: block;
  width: 150px;
  height: 150px;
  object-fit: contain;
  filter: none;
}

.most-viewed-copy {
  min-width: 0;
}

.most-viewed-heading .eyebrow {
  margin: 0 0 8px;
  color: #aeb8c7;
}

.most-viewed-eyebrow {
  display: inline-flex;
  align-items: center;
  letter-spacing: .14em;
}

.most-viewed-heading h2 {
  margin: 0;
  font-family: Manrope, sans-serif;
  font-size: clamp(27px, 4vw, 43px);
  font-weight: 600;
  letter-spacing: -.065em;
  line-height: 1.12;
}

.most-viewed-heading h2 em {
  color: #e8edf5;
  font-weight: 500;
}

.most-viewed-copy > p:last-child {
  margin: 0;
  color: var(--muted);
  font-size: 13px;
  line-height: 1.6;
}

.most-viewed-close {
  position: absolute;
  top: 0;
  right: 0;
  display: grid;
  width: 42px;
  height: 42px;
  flex: 0 0 auto;
  place-items: center;
  border: 1px solid rgba(255, 255, 255, .18);
  border-radius: 50%;
  background: rgba(255, 255, 255, .04);
  color: var(--text);
  cursor: pointer;
  transition: border-color .2s ease, color .2s ease;
}

.most-viewed-close:hover {
  border-color: rgba(255, 255, 255, .36);
  color: #fff;
}

.most-viewed-close:focus-visible {
  outline: 2px solid var(--accent-secondary);
  outline-offset: 3px;
  box-shadow: 0 0 0 5px color-mix(in srgb, var(--brand-accent-vivid) 14%, transparent);
}

.most-viewed-close svg {
  width: 18px;
  height: 18px;
  fill: none;
  stroke: currentColor;
  stroke-linecap: round;
  stroke-width: 1.7;
}

.most-viewed-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  align-items: center;
  gap: 30px;
}

.site-shell .most-viewed-card {
  min-width: 0;
  position: relative;
  z-index: 1;
  border: 1px solid rgba(255, 255, 255, .16);
  border-radius: 16px;
  background: #101010;
  box-shadow: 0 4px 14px rgba(0, 0, 0, .34);
}

.most-viewed-card:nth-child(1) {
  grid-column: 2;
  grid-row: 1;
  z-index: 2;
  transform: none;
}

.most-viewed-card:nth-child(2) {
  grid-column: 1;
  grid-row: 1;
  transform: none;
}

.most-viewed-card:nth-child(3) {
  grid-column: 3;
  grid-row: 1;
  transform: none;
}

.site-shell .most-viewed-card:hover,
.site-shell .most-viewed-card:nth-child(1):hover {
  transform: none;
  box-shadow: 0 4px 14px rgba(0, 0, 0, .34);
}

.site-shell .most-viewed-card:nth-child(2):hover,
.site-shell .most-viewed-card:nth-child(3):hover {
  transform: none;
  box-shadow: 0 4px 14px rgba(0, 0, 0, .34);
}

.most-viewed-card:hover .vehicle-image-wrap img {
  transform: none;
}

.most-viewed-card .vehicle-image-wrap::before {
  content: none;
}

.most-viewed-card .vehicle-image-wrap {
  width: calc(100% + 2px);
  height: clamp(135px, 16vw, 185px);
  margin: -1px -1px 0;
  border-radius: 17px 17px 0 0;
}

.most-viewed-card .most-viewed-info {
  gap: 15px;
  padding: 17px 18px 18px;
}

.most-viewed-skeleton-image {
  width: 100%;
  height: 100%;
}

.most-viewed-skeleton-make {
  width: 46%;
}

.most-viewed-skeleton-title {
  width: 74%;
  height: 19px;
}

.most-viewed-skeleton-details {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
}

.most-viewed-skeleton-chip {
  width: 68px;
  height: 25px;
  border-radius: 7px;
}

.most-viewed-skeleton-chip:last-child {
  width: 112px;
}

.most-viewed-skeleton-price {
  width: 76px;
  height: 16px;
}

.most-viewed-skeleton-button {
  width: 94px;
  height: 37px;
  flex: 0 0 auto;
  border-radius: 8px;
}

.most-viewed-title .vehicle-make {
  color: #aeb8c7;
  font-size: 9px;
  letter-spacing: .12em;
}

.most-viewed-title h3 {
  margin: 5px 0 0;
  font-family: Manrope, sans-serif;
  font-size: clamp(17px, 1.5vw, 21px);
  font-weight: 650;
  line-height: 1.2;
}

.most-viewed-title h3 a {
  color: #fff;
  text-decoration: none;
}

.most-viewed-details {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
}

.most-viewed-details span {
  padding: 6px 9px;
  border: 1px solid rgba(255, 255, 255, .09);
  border-radius: 7px;
  background: rgba(255, 255, 255, .035);
  color: #c5bfc0;
  font-size: 10px;
  line-height: 1.2;
}

.most-viewed-card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-top: 1px;
  padding-top: 13px;
  border-top: 1px solid rgba(255, 255, 255, .09);
}

.most-viewed-card-footer .vehicle-price-value strong {
  color: #fff;
  font-size: 15px;
  font-weight: 700;
}

.most-viewed-card-footer .vehicle-vat-note {
  font-size: 9px;
}

.most-viewed-view-button {
  display: inline-flex;
  min-height: 37px;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 0 13px;
  border: 1px solid rgba(255, 255, 255, .16);
  border-radius: 8px;
  background: #303030;
  color: #fff;
  cursor: pointer;
  font: inherit;
  font-size: 11px;
  font-weight: 700;
}

.most-viewed-view-button:hover {
  border-color: rgba(255, 255, 255, .2);
  background: #303030;
}

.most-viewed-view-button:focus-visible {
  outline: 2px solid var(--accent-secondary);
  outline-offset: 3px;
}

.most-viewed-card .vehicle-type {
  padding: 7px 11px;
  border: 1px solid rgba(255, 255, 255, .18);
  border-radius: 999px;
  background: rgba(8, 11, 16, .84);
  color: #d7dce5;
}

.most-viewed-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  margin-top: 21px;
  padding-top: 17px;
  border-top: 1px solid var(--line);
}

.most-viewed-footer > span {
  color: var(--muted);
  font-size: 11px;
}

.most-viewed-footer button {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  padding: 7px 0;
  border: 0;
  background: transparent;
  color: #d7dce5;
  cursor: pointer;
  font-size: 12px;
  font-weight: 700;
}

@media (max-width: 900px) {
  .most-viewed-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .most-viewed-card:nth-child(1),
  .most-viewed-card:nth-child(2),
  .most-viewed-card:nth-child(3) {
    grid-column: auto;
    grid-row: auto;
    margin-inline: 0;
    transform: none;
  }

  .most-viewed-card:last-child:nth-child(odd) {
    grid-column: 1 / -1;
    width: min(440px, 100%);
    justify-self: center;
  }
}

@media (max-width: 620px) {
  .most-viewed-overlay {
    padding: 10px;
  }

  .most-viewed-dialog {
    max-height: calc(100dvh - 20px);
    padding: 20px 15px 16px;
    border-radius: 14px;
  }

  .most-viewed-heading {
    margin-bottom: 24px;
  }

  .most-viewed-intro {
    max-width: calc(100% - 38px);
    gap: 8px;
  }

  .most-viewed-trophy {
    width: 104px;
    height: 104px;
  }

  .most-viewed-heading h2 {
    font-size: clamp(25px, 7.2vw, 34px);
  }

  .most-viewed-copy > p:last-child {
    max-width: 290px;
    font-size: 12px;
  }

  .most-viewed-close {
    width: 38px;
    height: 38px;
  }

  .most-viewed-grid {
    grid-template-columns: 1fr;
    gap: 18px;
  }

  .most-viewed-card:last-child:nth-child(odd) {
    grid-column: auto;
    width: auto;
  }

  .most-viewed-card:nth-child(1),
  .most-viewed-card:nth-child(2),
  .most-viewed-card:nth-child(3) {
    grid-column: auto;
    grid-row: auto;
    margin-inline: 0;
    transform: none;
  }

  .most-viewed-card .vehicle-image-wrap {
    height: 190px;
    width: calc(100% + 2px);
    margin: -1px -1px 0;
    border-radius: 17px 17px 0 0;
  }

  .most-viewed-card .most-viewed-info {
    padding: 14px;
  }

  .most-viewed-footer {
    align-items: flex-start;
    flex-direction: column;
    gap: 5px;
    margin-top: 15px;
    padding-top: 12px;
  }
}

