.site-shell[data-theme="admin"] .rental-admin-status .custom-select-popover {
  z-index: 80;
  border-color: rgba(145, 211, 165, .34);
  background: #101912;
  -webkit-backdrop-filter: none;
  backdrop-filter: none;
  box-shadow: 0 20px 46px rgba(0, 0, 0, .72), inset 0 1px rgba(255, 255, 255, .06);
}

.site-shell[data-theme="admin"] .rental-request-filters .custom-select-option,
.site-shell[data-theme="admin"] .rental-admin-status .custom-select-option {
  min-height: 40px;
  border-radius: 8px;
  color: #e4ede6;
}

.site-shell[data-theme="admin"] .rental-request-filters .custom-select-option:hover,
.site-shell[data-theme="admin"] .rental-request-filters .custom-select-option:focus-visible,
.site-shell[data-theme="admin"] .rental-admin-status .custom-select-option:hover,
.site-shell[data-theme="admin"] .rental-admin-status .custom-select-option:focus-visible {
  background: rgba(255, 255, 255, .09);
  color: #fff;
}

.site-shell[data-theme="admin"] .rental-request-filters .custom-select-option.is-selected,
.site-shell[data-theme="admin"] .rental-admin-status .custom-select-option.is-selected {
  background: rgba(83, 171, 106, .22);
  color: #a9edb8;
}

.rental-request-filters > label {
  display: grid;
  min-width: 0;
  gap: 6px;
  color: var(--muted);
  font-size: 10px;
  font-weight: 600;
}

.rental-request-filters input {
  width: 100%;
  min-width: 0;
  min-height: 40px;
  padding: 0 11px;
  border: 1px solid var(--line);
  border-radius: 7px;
  background: var(--surface);
  color: var(--text);
  font: inherit;
  font-size: 11px;
}

.rental-request-filters input:focus-visible {
  border-color: color-mix(in srgb, var(--accent) 70%, white 5%);
  outline: 2px solid color-mix(in srgb, var(--accent) 25%, transparent);
  outline-offset: 1px;
}

.rental-request-result-count {
  padding: 0 3px 11px;
  color: var(--muted);
  font-size: 10px;
  white-space: nowrap;
}

.rental-request-card .admin-purchase-summary {
  margin-top: 16px;
}

.rental-request-card {
  position: relative;
  overflow: visible;
  border: 1px solid rgba(220, 220, 220, .1);
  border-radius: 16px;
  background:
    radial-gradient(ellipse at 100% 0, color-mix(in srgb, var(--brand-accent-deep) 5.5%, transparent), transparent 43%),
    linear-gradient(145deg, rgba(18, 24, 32, .78), rgba(7, 10, 14, .94));
  box-shadow: inset 0 1px rgba(255, 255, 255, .035), 0 12px 30px rgba(0, 0, 0, .18);
  transition: border-color .2s ease, box-shadow .2s ease, transform .2s ease;
}

.rental-request-card:hover {
  transform: translateY(-2px);
  border-color: color-mix(in srgb, var(--brand-accent-deep) 24%, transparent);
  box-shadow: inset 0 1px rgba(255, 255, 255, .05), 0 16px 34px rgba(0, 0, 0, .25);
}

.rental-request-card:has(.rental-admin-status .custom-select.is-open) {
  z-index: 60;
}

.rental-admin-status .custom-select {
  z-index: 1;
}

.rental-admin-status .custom-select.is-open {
  z-index: 80;
}

.rental-request-card-header {
  align-items: center;
  padding-bottom: 13px;
  border-bottom: 1px solid rgba(220, 220, 220, .09);
}

.rental-request-card-header h3 {
  margin-top: 7px;
  font-size: 17px;
}

.rental-request-card-header time {
  padding: 6px 10px;
  border: 1px solid rgba(220, 220, 220, .09);
  border-radius: 999px;
  background: rgba(3, 5, 8, .25);
  font-variant-numeric: tabular-nums;
}

.rental-request-card .admin-submission-status {
  padding: 4px 9px;
  border-radius: 999px;
  font-size: 9px;
  font-weight: 700;
}

.rental-request-body {
  display: grid;
  grid-template-columns: 152px minmax(0, 1fr);
  gap: 18px;
  margin-top: 15px;
}

.rental-request-body > .admin-purchase-image {
  width: 152px;
  height: 118px;
  border: 1px solid rgba(220, 220, 220, .1);
  border-radius: 11px;
  background: #10161d;
  object-fit: cover;
}

.rental-request-info {
  display: grid;
  min-width: 0;
  grid-template-columns: minmax(130px, .75fr) minmax(180px, 1fr);
  align-content: start;
  gap: 10px 20px;
}

.rental-request-customer,
.rental-request-contacts {
  display: grid;
  min-width: 0;
  align-content: center;
  gap: 7px;
}

.rental-request-kicker {
  color: var(--muted);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: .1em;
}

.rental-request-customer > strong {
  overflow: hidden;
  color: var(--text);
  font-size: 14px;
  text-overflow: ellipsis;
}

.rental-request-contacts a {
  display: inline-flex;
  width: fit-content;
  max-width: 100%;
  align-items: center;
  gap: 7px;
  overflow-wrap: anywhere;
  color: var(--accent);
  font-size: 11px;
  text-decoration: none;
}

.rental-request-contacts a:hover {
  color: var(--text);
  text-decoration: underline;
}

.rental-request-contacts .site-icon {
  width: 14px;
  height: 14px;
  flex: 0 0 auto;
}

.rental-request-facts {
  display: grid;
  grid-column: 1 / -1;
  grid-template-columns: minmax(0, 1.4fr) minmax(120px, .8fr) minmax(120px, .75fr);
  gap: 12px;
  padding-top: 12px;
  border-top: 1px solid rgba(220, 220, 220, .09);
}

.rental-request-facts > div {
  display: grid;
  min-width: 0;
  align-content: start;
  gap: 6px;
}

.rental-request-facts > div + div {
  padding-left: 14px;
  border-left: 1px solid rgba(220, 220, 220, .09);
}

.rental-request-period > strong {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 5px;
  color: var(--text);
  font-size: 12px;
  font-variant-numeric: tabular-nums;
}

.rental-request-period > strong > span {
  color: var(--muted);
}

.rental-request-facts small {
  display: flex;
  align-items: center;
  gap: 5px;
  color: var(--muted);
  font-size: 10px;
}

.rental-request-period small .site-icon {
  width: 13px;
  height: 13px;
}

.rental-request-estimate > strong {
  color: var(--text);
  font-family: Manrope, sans-serif;
  font-size: 17px;
  font-variant-numeric: tabular-nums;
  font-weight: 700;
}

.rental-email-status {
  width: fit-content;
  color: var(--muted);
  font-size: 11px;
  font-weight: 600;
}

.rental-email-status.is-sent {
  color: #8be1ad;
}

.rental-email-status.is-failed {
  color: #ff9a91;
}

.rental-request-customer-message {
  margin: 14px 0 0 170px;
  padding: 0 0 0 12px;
  border-left: 2px solid var(--accent);
  color: var(--muted);
  font-size: 12px;
  line-height: 1.6;
  overflow-wrap: anywhere;
}

.rental-admin-status {
  display: grid;
  grid-template-columns: minmax(150px, 1fr) auto auto;
  align-items: end;
  gap: 12px;
  margin: 16px 0 0;
  padding-top: 13px;
  border-top: 1px solid rgba(220, 220, 220, .09);
}

.rental-admin-status > label {
  display: grid;
  min-width: 0;
  gap: 7px;
  color: var(--muted);
  font-size: 11px;
}

.rental-admin-status .button {
  min-height: 40px;
}

.rental-mark-contacted {
  display: inline-flex;
  min-height: 40px;
  align-items: center;
  justify-content: center;
  gap: 7px;
  padding: 0 13px;
  border: 1px solid color-mix(in srgb, var(--brand-accent-deep) 25%, transparent);
  border-radius: 999px;
  background: color-mix(in srgb, var(--brand-accent-deep) 7%, transparent);
  color: var(--accent);
  cursor: pointer;
  font: inherit;
  font-size: 11px;
  font-weight: 600;
  transition: background .18s ease, border-color .18s ease;
}

.rental-mark-contacted:hover:not(:disabled) {
  border-color: color-mix(in srgb, var(--brand-accent-deep) 50%, transparent);
  background: color-mix(in srgb, var(--brand-accent-deep) 13%, transparent);
}

.rental-mark-contacted:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 3px;
}

.rental-mark-contacted:disabled {
  cursor: wait;
  opacity: .65;
}

.rental-mark-contacted .site-icon {
  width: 14px;
  height: 14px;
}

.rental-request-card > .form-error,
.rental-request-card > .form-success {
  margin: 12px 0 0;
}

@media (max-width: 1000px) {
  .rental-request-filters {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .rental-request-search {
    grid-column: 1 / -1;
  }

  .rental-request-facts {
    grid-template-columns: minmax(0, 1.2fr) minmax(110px, .8fr);
  }

  .rental-request-notification {
    grid-column: 1 / -1;
    padding: 9px 0 0 !important;
    border-top: 1px solid rgba(220, 220, 220, .09);
    border-left: 0 !important;
  }
}

@media (max-width: 520px) {
  .rental-request-filters {
    grid-template-columns: minmax(0, 1fr);
    padding: 11px;
  }

  .rental-request-search {
    grid-column: auto;
  }

  .rental-request-result-count {
    padding: 2px 0 0;
  }

  .rental-request-body {
    grid-template-columns: minmax(0, 1fr);
    gap: 12px;
  }

  .rental-request-body > .admin-purchase-image {
    width: 100%;
    height: 150px;
  }

  .rental-request-info {
    grid-template-columns: minmax(0, 1fr);
  }

  .rental-request-facts {
    grid-template-columns: minmax(0, 1fr) minmax(0, .8fr);
    gap: 10px;
  }

  .rental-request-facts > div + div {
    padding-left: 10px;
  }

  .rental-request-notification {
    grid-column: 1 / -1;
    padding: 9px 0 0 !important;
    border-top: 1px solid rgba(220, 220, 220, .09);
    border-left: 0 !important;
  }

  .rental-request-customer-message {
    margin-left: 0;
  }

  .rental-admin-status {
    grid-template-columns: minmax(0, 1fr);
    gap: 9px;
  }

  .rental-admin-status > button {
    width: 100%;
  }
}

.admin-submission-title {
  flex-wrap: wrap;
  align-items: center;
}

.admin-submission-contact {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 14px;
  padding: 12px 14px;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: rgba(8, 11, 16, .72);
}

.admin-submission-response {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  align-items: end;
  gap: 12px;
  margin-top: 16px;
  padding: 16px;
  border: 1px solid var(--line);
  border-radius: 11px;
  background: rgba(8, 11, 16, .55);
}

.admin-submission-response > label {
  display: grid;
  min-width: 0;
  gap: 7px;
  color: var(--muted);
  font-size: 11px;
}

.admin-submission-response .admin-response-message {
  grid-column: 1 / -1;
}

.admin-submission-response :is(input, textarea, .custom-select-trigger) {
  min-width: 0;
  border-radius: 9px;
}

.admin-vehicle-metrics {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
  margin-top: 8px;
}

.admin-vehicle-metrics span {
  display: inline-flex;
  min-height: 27px;
  align-items: center;
  gap: 6px;
  padding: 4px 8px;
  border: 1px solid color-mix(in srgb, var(--brand-accent-deep) 18%, transparent);
  border-radius: 7px;
  background: color-mix(in srgb, var(--brand-accent-deep) 5.5%, transparent);
  color: #b7cce0;
  font-size: 10px;
  line-height: 1.3;
}

.admin-vehicle-metrics .site-icon {
  width: 14px;
  height: 14px;
  color: var(--accent);
}

.admin-metrics-note {
  margin: 8px 0 16px;
  color: var(--muted);
  font-size: 11px;
  line-height: 1.5;
}

@media (max-width: 760px) {
  .admin-submission {
    grid-template-columns: minmax(0, 1fr);
  }

  .admin-submission-photos {
    grid-template-columns: repeat(auto-fill, minmax(82px, 1fr));
  }
}

@media (max-width: 480px) {
  .admin-submissions {
    padding: 16px;
  }

  .admin-submission-response {
    grid-template-columns: minmax(0, 1fr);
    padding: 12px;
  }

  .admin-submission-response .admin-response-message {
    grid-column: auto;
  }
}

.admin-analytics {
  display: grid;
  gap: 18px;
  margin-bottom: 24px;
  padding: clamp(18px, 2.5vw, 28px);
  border: 1px solid var(--line);
  border-radius: 17px;
  background:
    radial-gradient(ellipse at 0 0, color-mix(in srgb, var(--accent) 10%, transparent), transparent 48%),
    linear-gradient(145deg, var(--surface-raised), #07090d 85%);
  box-shadow: 0 20px 50px rgba(0, 0, 0, .24), inset 0 1px rgba(255, 255, 255, .035);
}

.admin-analytics-heading,
.admin-analytics-chart-heading {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 18px;
}

.admin-analytics-heading h2 {
  margin: 4px 0 6px;
  font-family: Manrope, sans-serif;
  font-size: clamp(23px, 3vw, 32px);
  font-weight: 600;
  letter-spacing: -.05em;
}

.admin-analytics-heading h2 em {
  color: var(--accent);
  font-style: normal;
}

.admin-analytics-heading > div > p:last-child,
.admin-analytics-chart-heading p {
  margin: 0;
  color: var(--muted);
  font-size: 12px;
  line-height: 1.6;
}

.admin-analytics-filter {
  display: grid;
  min-width: 170px;
  gap: 6px;
  color: var(--muted);
  font-size: 11px;
}

.admin-analytics-kpis {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 12px;
}

.admin-analytics-make-logo {
  display: grid;
  width: 60px;
  height: 60px;
  flex: 0 0 auto;
  place-items: center;
  overflow: hidden;
  border: 0;
  border-radius: 0;
  background: transparent;
  color: var(--accent);
  font-size: 13px;
  font-weight: 700;
}

.admin-analytics-make-logo img {
  width: 100%;
  height: 100%;
  padding: 0;
  object-fit: contain;
}

.admin-analytics-insights-note {
  grid-column: 1 / -1;
  margin: -2px 0 0;
  color: var(--muted);
  font-size: 10px;
  line-height: 1.5;
}

.admin-analytics-panels {
  display: grid;
  grid-template-columns: minmax(320px, .82fr) minmax(0, 1.18fr);
  align-items: stretch;
  gap: 14px;
}

.admin-interest-gauge {
  display: flex;
  min-width: 0;
  min-height: 430px;
  flex-direction: column;
  align-items: center;
  padding: clamp(16px, 2vw, 22px);
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 13px;
  background:
    radial-gradient(ellipse at 50% 34%, color-mix(in srgb, var(--accent) 10%, transparent), transparent 58%),
    linear-gradient(160deg, rgba(255, 255, 255, .035), rgba(3, 5, 8, .72) 78%);
}

.admin-interest-gauge-heading {
  display: flex;
  width: 100%;
  align-items: flex-start;
  justify-content: space-between;
  gap: 10px;
}

.admin-interest-gauge-heading .eyebrow {
  margin: 0 0 5px;
  font-size: 9px;
}

.admin-interest-gauge-heading h3 {
  margin: 0;
  color: var(--text);
  font-family: Manrope, sans-serif;
  font-size: 17px;
  letter-spacing: -.035em;
}

.admin-interest-gauge-live {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 5px 7px;
  border: 1px solid var(--line);
  border-radius: 99px;
  color: var(--muted);
  font-size: 8px;
  letter-spacing: .08em;
  white-space: nowrap;
}

.admin-interest-gauge-live i {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--accent);
  box-shadow: 0 0 9px color-mix(in srgb, var(--accent) 65%, transparent);
}

.admin-interest-gauge-face {
  display: block;
  width: min(100%, 390px);
  height: auto;
  margin: 12px auto -21px;
  overflow: visible;
}

.admin-interest-gauge-track,
.admin-interest-gauge-progress {
  fill: none;
  stroke-linecap: round;
  stroke-width: 12px;
}

.admin-interest-gauge-track {
  stroke: rgba(255, 255, 255, .075);
}

.admin-interest-gauge-progress {
  filter: drop-shadow(0 0 5px color-mix(in srgb, var(--accent) 42%, transparent));
  stroke: url(#interest-gauge-gradient);
  transition: stroke-dasharray 1.1s cubic-bezier(.2, .75, .25, 1);
}

.admin-interest-gauge-tick {
  stroke: rgba(213, 226, 239, .32);
  stroke-linecap: round;
  stroke-width: 1.5px;
}

.admin-interest-gauge-tick.is-major {
  stroke: color-mix(in srgb, var(--accent) 72%, white);
  stroke-width: 2px;
}

.admin-interest-gauge-scale {
  fill: var(--muted);
  font-family: inherit;
  font-size: 9px;
  font-variant-numeric: tabular-nums;
}

.admin-interest-gauge-needle {
  transform-box: view-box;
  transform-origin: 160px 160px;
  transition: transform 1.2s cubic-bezier(.18, .8, .25, 1.15);
}

.admin-interest-gauge-needle path {
  fill: #f5f8fc;
  filter: drop-shadow(0 0 4px rgba(255, 255, 255, .36));
}

.admin-interest-gauge-hub-outer {
  fill: #27272a;
  stroke: color-mix(in srgb, var(--accent) 55%, #fff);
  stroke-width: 2px;
}

.admin-interest-gauge-hub {
  fill: var(--accent);
  filter: url(#interest-gauge-glow);
}

.admin-interest-gauge-readout {
  display: grid;
  justify-items: center;
  gap: 3px;
  margin-top: 0;
  text-align: center;
}

.admin-interest-gauge-readout strong {
  color: var(--text);
  font-family: Manrope, sans-serif;
  font-size: clamp(33px, 4vw, 46px);
  font-variant-numeric: tabular-nums;
  font-weight: 600;
  letter-spacing: -.06em;
  line-height: 1;
  text-shadow: 0 0 24px color-mix(in srgb, var(--accent) 18%, transparent);
}

.admin-interest-gauge-readout strong span {
  margin-left: 2px;
  color: var(--accent);
  font-size: .56em;
}

.admin-interest-gauge-readout > span {
  color: var(--muted);
  font-size: 9px;
}

.admin-interest-gauge-odometer {
  display: grid;
  width: 100%;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
  margin-top: 17px;
}

.admin-interest-gauge-odometer > div {
  display: grid;
  min-width: 0;
  gap: 5px;
  padding: 9px 10px;
  border: 1px solid rgba(255, 255, 255, .075);
  border-radius: 8px;
  background: linear-gradient(180deg, #0d1218, #1c1c1f);
  box-shadow: inset 0 1px rgba(255, 255, 255, .035), 0 5px 12px rgba(0, 0, 0, .15);
}

.admin-interest-gauge-odometer span {
  overflow: hidden;
  color: var(--muted);
  font-size: 8px;
  letter-spacing: .08em;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.admin-interest-gauge-odometer strong {
  overflow: hidden;
  color: #e9f2fb;
  font-family: "Courier New", monospace;
  font-size: clamp(13px, 1.5vw, 17px);
  font-variant-numeric: tabular-nums;
  letter-spacing: .09em;
  text-overflow: clip;
  white-space: nowrap;
}

.admin-interest-gauge-note {
  margin: 10px 0 0;
  color: var(--muted);
  font-size: 9px;
  line-height: 1.5;
  text-align: center;
}

.admin-analytics-kpi {
  position: relative;
  display: grid;
  min-width: 0;
  min-height: 150px;
  grid-template-rows: auto 1fr auto;
  align-items: end;
  gap: 5px;
  padding: 16px;
  overflow: hidden;
  border: 1px solid rgba(220, 220, 220, .11);
  border-radius: 13px;
  background:
    radial-gradient(ellipse at 100% 0, color-mix(in srgb, var(--accent) 10%, transparent), transparent 55%),
    linear-gradient(150deg, rgba(20, 28, 38, .82), rgba(7, 9, 13, .92) 78%);
  box-shadow: inset 0 1px rgba(255, 255, 255, .04), 0 8px 22px rgba(0, 0, 0, .13);
  transition: transform .22s ease, border-color .22s ease, box-shadow .22s ease, background .22s ease;
}

.admin-analytics-kpi:hover {
  transform: translateY(-3px);
  border-color: color-mix(in srgb, var(--accent) 48%, var(--line));
  box-shadow: inset 0 1px rgba(255, 255, 255, .06), 0 13px 28px rgba(0, 0, 0, .24);
}

.admin-analytics-icon {
  position: relative;
  z-index: 1;
  display: grid;
  width: 34px;
  height: 34px;
  grid-row: 1;
  place-items: center;
  border: 1px solid color-mix(in srgb, var(--accent) 34%, transparent);
  border-radius: 10px;
  background: color-mix(in srgb, var(--accent) 11%, #090d12);
  color: var(--accent);
  box-shadow: inset 0 1px rgba(255, 255, 255, .08);
}

.admin-analytics-icon .site-icon {
  width: 18px;
  height: 18px;
}

.admin-analytics-kpi-label {
  position: absolute;
  top: 24px;
  right: 15px;
  left: 60px;
  overflow: hidden;
  color: var(--muted);
  font-size: 10px;
  font-weight: 600;
