  border-radius: 10px;
  background: rgba(255, 255, 255, .02);
  color: var(--text);
  cursor: pointer;
  transition: border-color .2s ease, box-shadow .2s ease, background .2s ease;
}

.admin-warranty-trigger:hover {
  border-color: color-mix(in srgb, var(--accent) 38%, var(--line));
  box-shadow: 0 0 0 1px rgba(104, 178, 141, .08);
}

.admin-warranty-trigger.is-open {
  border-color: color-mix(in srgb, var(--accent) 55%, var(--line));
  background: rgba(104, 178, 141, .05);
}

.admin-warranty-trigger-copy {
  display: flex;
  min-width: 0;
  flex-direction: column;
  align-items: flex-start;
  gap: 2px;
}

.admin-warranty-trigger-label {
  color: var(--muted);
  font-size: 10px;
  letter-spacing: .08em;
  text-transform: uppercase;
}

.admin-warranty-trigger strong {
  overflow: hidden;
  max-width: 100%;
  color: var(--text);
  font-size: 12px;
  font-weight: 600;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.admin-warranty-trigger-icon {
  width: 18px;
  height: 18px;
  color: var(--muted);
  transition: transform .2s ease;
}

.admin-warranty-trigger.is-open .admin-warranty-trigger-icon {
  transform: rotate(90deg);
}

.admin-warranty-menu {
  display: none;
  margin-top: 12px;
  padding-top: 12px;
  border-top: 1px solid var(--line);
}

.admin-warranty-menu.is-open {
  display: block;
}

.admin-warranty-options {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.admin-warranty-options label {
  position: relative;
  display: inline-flex;
  min-height: 38px;
  flex: 0 1 auto;
  align-items: center;
  gap: 8px;
  padding: 7px 10px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: color-mix(in srgb, var(--brand-accent-deep) 4.5%, transparent);
  color: #d7e1eb;
  font-size: 11px;
  line-height: 1.3;
  cursor: pointer;
  transition: border-color .2s ease, background .2s ease, transform .2s ease, color .2s ease;
}

.admin-warranty-options label:hover {
  transform: translateY(-1px);
  border-color: color-mix(in srgb, var(--accent) 42%, var(--line));
  color: var(--text);
}

.admin-warranty-options label:has(input:checked) {
  border-color: color-mix(in srgb, var(--accent) 55%, var(--line));
  background: color-mix(in srgb, var(--accent) 11%, transparent);
  color: var(--text);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--accent) 8%, transparent);
}

.admin-warranty-options input {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: 0;
  overflow: hidden;
  opacity: 0;
  clip-path: inset(50%);
  flex: 0 0 auto;
}

.admin-warranty-checkbox {
  display: grid;
  width: 17px;
  height: 17px;
  flex: 0 0 17px;
  place-items: center;
  border: 1px solid rgba(220, 220, 220, .3);
  border-radius: 5px;
  background: rgba(3, 5, 8, .45);
  transition: border-color .18s ease, background .18s ease, box-shadow .18s ease;
}

.admin-warranty-checkbox::after {
  width: 4px;
  height: 8px;
  border: solid #08110d;
  border-width: 0 2px 2px 0;
  content: '';
  opacity: 0;
  transform: translateY(-1px) rotate(45deg) scale(.7);
  transition: opacity .16s ease, transform .16s ease;
}

.admin-warranty-options input:checked + .admin-warranty-checkbox {
  border-color: var(--accent);
  background: var(--accent);
  box-shadow: 0 0 0 2px color-mix(in srgb, var(--accent) 15%, transparent);
}

.admin-warranty-options input:checked + .admin-warranty-checkbox::after {
  opacity: 1;
  transform: translateY(-1px) rotate(45deg) scale(1);
}

.admin-warranty-options input:focus-visible + .admin-warranty-checkbox {
  outline: 2px solid color-mix(in srgb, var(--accent) 75%, white);
  outline-offset: 3px;
}

