.progressive-image {
  position: relative;
  display: block;
  overflow: hidden;
  background: #181818;
  color: #a9bac9;
  isolation: isolate;
}

.progressive-image > img {
  position: absolute;
  z-index: 1;
  inset: 0;
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
  opacity: 0;
  transition: opacity .32s ease, transform .55s ease;
}

.progressive-image.is-loaded > img {
  opacity: 1;
}

.progressive-image-placeholder {
  position: absolute;
  z-index: 2;
  inset: 0;
  display: grid;
  align-content: center;
  justify-items: center;
  gap: 8px;
  overflow: hidden;
  background: linear-gradient(110deg, transparent 20%, rgba(255, 255, 255, .12) 46%, transparent 72%);
  background-size: 220% 100%;
  color: #aab8c5;
  font-size: 10px;
  line-height: 1.4;
  text-align: center;
  animation: media-placeholder-shimmer 1.7s ease-in-out infinite;
}

.progressive-image-placeholder > span:not(.progressive-image-mark) {
  padding-inline: 8px;
}

.progressive-image-mark {
  display: grid;
  width: 32px;
  height: 32px;
  place-items: center;
  border: 1px solid rgba(255, 255, 255, .12);
  border-radius: 10px;
  background: rgba(255, 255, 255, .06);
  color: #bdbdbd;
  animation: media-placeholder-pulse 1.7s ease-in-out infinite;
}

.progressive-image-mark .site-icon {
  width: 17px;
  height: 17px;
}

.progressive-image-mark.is-static {
  color: #8895a1;
  animation: none;
}

.progressive-image-placeholder button {
  min-height: 30px;
  padding: 5px 12px;
  border: 1px solid color-mix(in srgb, var(--brand-accent-deep) 38%, transparent);
  border-radius: 999px;
  background: var(--brand-accent-surface);
  color: #f1dfe1;
  cursor: pointer;
  font: inherit;
  font-size: 10px;
  font-weight: 700;
}

.progressive-image-placeholder button:hover,
.progressive-image-placeholder button:focus-visible {
  border-color: var(--accent);
  background: var(--brand-accent-surface-hover);
  outline: none;
}

