.sold-cars-steps {
  position: relative;
  display: grid;
  width: min(760px, 100%);
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 18px;
  margin: 0 auto 12px;
  padding: 16px 0 22px;
  list-style: none;
  isolation: isolate;
}

.sold-cars-steps::before,
.sold-cars-steps::after {
  position: absolute;
  z-index: -1;
  top: 37px;
  left: 16.66%;
  width: 66.68%;
  height: 2px;
  border-radius: 2px;
  content: '';
}

.sold-cars-steps::before {
  background: color-mix(in srgb, var(--accent) 17%, var(--line));
}

.sold-cars-steps::after {
  background: linear-gradient(90deg, var(--accent), color-mix(in srgb, var(--accent) 30%, #fff));
  box-shadow: 0 0 12px color-mix(in srgb, var(--accent) 50%, transparent);
  transform: scaleX(0);
  transform-origin: left center;
  animation: sold-cars-steps-progress 8s ease-in-out infinite;
}

.sold-cars-step {
  display: flex;
  min-width: 0;
  align-items: center;
  flex-direction: column;
  gap: 9px;
  color: var(--muted);
  text-align: center;
}

.sold-cars-step-icon {
  display: grid;
  width: 44px;
  height: 44px;
  place-items: center;
  border: 1px solid color-mix(in srgb, var(--accent) 34%, var(--line));
  border-radius: 50%;
  background: color-mix(in srgb, var(--surface) 92%, #000);
  color: color-mix(in srgb, var(--accent) 72%, #fff);
  box-shadow: 0 0 0 5px var(--bg);
  animation: sold-cars-step-pulse 8s ease-in-out infinite;
}

.sold-cars-step:nth-child(2) .sold-cars-step-icon {
  animation-delay: 2.45s;
}

.sold-cars-step:nth-child(3) .sold-cars-step-icon {
  animation-delay: 4.9s;
}

.sold-cars-step-icon .site-icon {
  width: 19px;
  height: 19px;
}

.sold-cars-step-copy {
  display: flex;
  align-items: center;
  flex-direction: column;
  gap: 3px;
  font-size: 12px;
  font-weight: 650;
  line-height: 1.35;
}

.sold-cars-step-copy small {
  color: var(--accent);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: .14em;
}

@keyframes sold-cars-steps-progress {
  0%, 5% { transform: scaleX(0); }
  28%, 31% { transform: scaleX(.24); }
  52%, 55% { transform: scaleX(.5); }
  76%, 79% { transform: scaleX(1); }
  100% { transform: scaleX(1); }
}

@keyframes sold-cars-step-pulse {
  0%, 8%, 100% {
    border-color: color-mix(in srgb, var(--accent) 34%, var(--line));
    color: color-mix(in srgb, var(--accent) 72%, #fff);
    box-shadow: 0 0 0 5px var(--bg);
    transform: scale(1);
  }
  15%, 28% {
    border-color: var(--accent);
    color: #fff;
    box-shadow: 0 0 0 5px var(--bg), 0 0 20px color-mix(in srgb, var(--accent) 48%, transparent);
    transform: scale(1.12);
  }
}

@media (max-width: 520px) {
  .sold-cars-steps {
    gap: 6px;
    padding-block: 12px 18px;
  }

  .sold-cars-steps::before,
  .sold-cars-steps::after {
    top: 33px;
  }

  .sold-cars-step-icon {
    width: 40px;
    height: 40px;
  }

  .sold-cars-step-copy {
    font-size: 10px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .sold-cars-steps::after,
  .sold-cars-step-icon {
    animation: none;
  }

  .sold-cars-steps::after {
    transform: scaleX(1);
  }
}

