.admin-console-kicker {
  display: flex;
  align-items: center;
  gap: 7px;
  color: var(--admin-console-muted);
  font-size: 9px;
  font-weight: 800;
  letter-spacing: .14em;
}

.admin-console-kicker i {
  width: 3px;
  height: 3px;
  border-radius: 50%;
  background: var(--brand-accent);
}

.admin-console-title > strong {
  overflow: hidden;
  color: #f3f4f6;
  font-family: Manrope, sans-serif;
  font-size: 16px;
  font-weight: 700;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.admin-global-search {
  position: relative;
  z-index: 30;
  min-width: 0;
}

.admin-global-search-form {
  display: flex;
  min-height: 46px;
  align-items: center;
  gap: 10px;
  padding: 0 12px;
  border: 1px solid var(--admin-console-border);
  border-radius: 10px;
  background: #17191e;
  color: var(--admin-console-muted);
  transition: border-color .18s ease, box-shadow .18s ease;
}

.admin-global-search-form:focus-within {
  border-color: color-mix(in srgb, var(--brand-accent) 60%, transparent);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--brand-accent) 12%, transparent);
}

.admin-global-search-form > .site-icon {
  width: 18px;
  height: 18px;
  flex: 0 0 auto;
}

.admin-global-search-form input {
  width: 100%;
  min-width: 0;
  padding: 10px 0;
  border: 0;
  outline: 0;
  background: transparent;
  color: #f3f4f6;
  font-size: 12px;
}

.admin-global-search-form input::placeholder {
  color: #747d88;
}

.admin-global-search-form input:focus-visible {
  outline: 0;
  box-shadow: none;
}

.admin-global-search-form kbd {
  flex: 0 0 auto;
  padding: 3px 6px;
  border: 1px solid rgba(255, 255, 255, .1);
  border-radius: 5px;
  color: #8d95a0;
  font: 700 8px/1.3 Roboto, sans-serif;
  letter-spacing: .06em;
}

.admin-search-clear {
  display: grid;
  width: 26px;
  height: 26px;
  flex: 0 0 auto;
  place-items: center;
  padding: 0;
  border: 0;
  border-radius: 6px;
  background: transparent;
  color: #aab0ba;
  cursor: pointer;
}

.admin-search-clear:hover {
  background: rgba(255, 255, 255, .08);
  color: #fff;
}

.admin-search-clear .site-icon {
  width: 14px;
  height: 14px;
}

.admin-search-results,
.admin-notifications-panel {
  position: absolute;
  top: calc(100% + 9px);
  right: 0;
  left: 0;
  overflow: hidden;
  padding: 7px;
  border: 1px solid rgba(255, 255, 255, .12);
  border-radius: 12px;
  background: #15171b;
  box-shadow: 0 18px 48px rgba(0, 0, 0, .48);
}

.admin-search-results > button {
  display: grid;
  width: 100%;
  min-height: 56px;
  grid-template-columns: 34px minmax(0, 1fr) 16px;
  align-items: center;
  gap: 10px;
  padding: 8px 10px;
  border: 0;
  border-radius: 8px;
  background: transparent;
  color: #f2f3f5;
  cursor: pointer;
  text-align: left;
}

.admin-search-results > button:hover,
.admin-search-results > button:focus-visible {
  background: rgba(255, 255, 255, .06);
}

.admin-search-result-icon {
  display: grid;
  width: 32px;
  height: 32px;
  place-items: center;
  border: 1px solid rgba(255, 255, 255, .1);
  border-radius: 8px;
  color: #d3a2a7;
}

.admin-search-result-icon .site-icon,
.admin-search-result-arrow {
  width: 16px;
  height: 16px;
}

.admin-search-results > button > span:nth-child(2) {
  display: grid;
  min-width: 0;
  gap: 4px;
}

.admin-search-results strong,
.admin-search-results small {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.admin-search-results strong {
  font-size: 11px;
  font-weight: 700;
}

.admin-search-results small {
  color: var(--admin-console-muted);
  font-size: 10px;
}

.admin-search-result-arrow {
  color: #77808c;
}

.admin-search-empty,
.admin-notifications-panel > p {
  margin: 0;
  padding: 14px 12px;
  color: var(--admin-console-muted);
  font-size: 11px;
}

.admin-console-tools {
  display: flex;
  min-width: 0;
  align-items: center;
  justify-content: flex-end;
  gap: clamp(10px, 1.5vw, 22px);
}

.admin-console-datetime {
  display: grid;
  gap: 2px;
  padding-right: clamp(8px, 1.5vw, 20px);
  border-right: 1px solid var(--admin-console-border);
  text-align: right;
  white-space: nowrap;
}

.admin-console-datetime span {
  color: var(--admin-console-muted);
  font-size: 10px;
  text-transform: capitalize;
}

.admin-console-datetime strong {
  color: #f2f3f5;
  font-size: 14px;
  font-variant-numeric: tabular-nums;
}

.admin-notifications {
  position: relative;
}

.admin-notifications-toggle {
  position: relative;
  display: grid;
  width: 40px;
  height: 40px;
  place-items: center;
  padding: 0;
  border: 1px solid var(--admin-console-border);
  border-radius: 9px;
  background: #17191e;
  color: #e7e9ed;
  cursor: pointer;
}

.admin-notifications-toggle:hover,
.admin-notifications-toggle[aria-expanded="true"] {
  border-color: rgba(220, 92, 105, .45);
  background: rgba(166, 42, 56, .12);
}

.admin-notifications-toggle > svg {
  width: 18px;
  height: 18px;
  fill: none;
  stroke: currentColor;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-width: 1.6;
}

.admin-notifications-toggle > span {
  position: absolute;
  top: -6px;
  right: -6px;
  display: grid;
  min-width: 17px;
  height: 17px;
  place-items: center;
  padding: 0 4px;
  border: 2px solid #0d0f13;
  border-radius: 9px;
  background: var(--brand-accent);
  color: #fff;
  font-size: 9px;
  font-weight: 800;
}

.admin-notifications-panel {
  right: -10px;
  left: auto;
  width: min(310px, calc(100vw - 32px));
  padding: 12px;
}

.admin-notifications-panel > strong {
  display: block;
  padding: 3px 6px 9px;
  color: #f1f2f4;
  font-size: 12px;
}

.admin-notifications-panel > button {
  display: flex;
  width: 100%;
  min-height: 42px;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 8px 7px;
  border: 0;
  border-top: 1px solid rgba(255, 255, 255, .06);
  background: transparent;
  color: #cbd0d7;
  cursor: pointer;
  font-size: 11px;
  text-align: left;
}

.admin-notifications-panel > button:hover {
  color: #fff;
}

.admin-notifications-panel > button b {
  color: #ef9ca4;
  font-size: 11px;
}

.admin-account-summary {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: 9px;
}

.admin-account-avatar {
  display: grid;
  width: 36px;
  height: 36px;
  flex: 0 0 auto;
  place-items: center;
  border: 1px solid rgba(220, 92, 105, .34);
  border-radius: 50%;
  background: linear-gradient(145deg, rgba(187, 51, 65, .25), rgba(255, 255, 255, .04));
  color: #f0c2c6;
  font-size: 10px;
  font-weight: 800;
}

.admin-account-summary > span:last-child {
  display: grid;
  min-width: 0;
  gap: 3px;
}

.admin-account-summary strong,
.admin-account-summary small {
  overflow: hidden;
  max-width: 140px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.admin-account-summary strong {
  color: #f1f2f4;
  font-size: 11px;
}

.admin-account-summary small {
  color: var(--admin-console-muted);
  font-size: 9px;
}

.admin-logout-button {
  min-height: 34px;
  padding: 0 11px;
  border: 1px solid var(--admin-console-border);
  border-radius: 7px;
  background: transparent;
  color: #b6bdc7;
  cursor: pointer;
  font-size: 10px;
  font-weight: 700;
}

.admin-logout-button:hover {
  border-color: rgba(220, 92, 105, .4);
  color: #fff;
}

.admin-main-layout {
  min-height: 100vh;
  padding: 120px clamp(18px, 3vw, 48px) 48px;
}

.admin-main-layout.is-authenticated-admin {
  display: grid;
  width: min(100%, 1840px);
  grid-template-columns: 248px minmax(0, 1fr);
  align-items: start;
  gap: clamp(18px, 2.2vw, 34px);
  margin: 0 auto;
}

.admin-main-layout .route-content {
  display: contents;
}

.admin-main-content {
  min-width: 0;
}

.admin-sidebar {
  position: sticky;
  top: 112px;
  display: flex;
  min-height: min(700px, calc(100vh - 140px));
  flex-direction: column;
  padding: 15px 11px;
  border: 1px solid var(--admin-console-border);
  border-radius: 14px;
  background: linear-gradient(165deg, #15171b, #101216 72%);
  box-shadow: 0 16px 38px rgba(0, 0, 0, .2);
}

.admin-sidebar-heading {
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 7px 8px 17px;
  border-bottom: 1px solid var(--admin-console-border);
}

.admin-sidebar-mark {
  display: grid;
  width: 34px;
  height: 34px;
  flex: 0 0 auto;
  place-items: center;
  border: 1px solid rgba(220, 92, 105, .32);
  border-radius: 9px;
  background: rgba(171, 42, 57, .12);
  color: #f0a3ab;
  font-size: 10px;
  font-weight: 900;
  letter-spacing: -.04em;
}

.admin-sidebar-heading > span:last-child,
.admin-sidebar-footer > span:last-child {
  display: grid;
  gap: 4px;
}

.admin-sidebar-heading strong {
  color: #f0f1f3;
  font-size: 12px;
}

.admin-sidebar-heading small {
  color: #828b97;
  font-size: 8px;
  font-weight: 700;
  letter-spacing: .1em;
}

.admin-section-navigation {
  display: grid;
  gap: 5px;
  margin-top: 14px;
}

.admin-section-navigation button {
  display: grid;
  width: 100%;
  min-width: 0;
  min-height: 47px;
  grid-template-columns: 23px minmax(0, 1fr) auto;
  align-items: center;
  justify-content: initial;
  gap: 10px;
  padding: 0 10px;
  border: 1px solid transparent;
  border-radius: 8px;
  background: transparent;
  color: #a4abb5;
  cursor: pointer;
  text-align: left;
  transition: background .16s ease, color .16s ease, border-color .16s ease;
}

.admin-section-navigation button:hover,
.admin-section-navigation button:focus-visible {
  border-color: rgba(255, 255, 255, .06);
  background: rgba(255, 255, 255, .045);
  color: #f4f5f6;
}

.admin-section-navigation button.is-active {
  border-color: rgba(221, 88, 102, .2);
  background: linear-gradient(90deg, rgba(177, 42, 57, .2), rgba(177, 42, 57, .06));
  color: #fff;
  box-shadow: inset 2px 0 #d35c69;
}

.admin-section-navigation-icon {
  display: grid;
  width: 23px;
  height: 23px;
  place-items: center;
}

.admin-section-navigation-icon .site-icon {
  width: 17px;
  height: 17px;
}

.admin-section-navigation-label {
  overflow: hidden;
  font-size: 11px;
  font-weight: 600;
  line-height: 1.3;
  text-overflow: ellipsis;
}

.admin-section-navigation-count {
  display: grid;
  min-width: 20px;
  height: 20px;
  place-items: center;
  padding: 0 5px;
  border: 1px solid rgba(255, 255, 255, .08);
  border-radius: 10px;
  background: rgba(255, 255, 255, .04);
  color: #bbc1ca;
  font-size: 9px;
  font-variant-numeric: tabular-nums;
}

.admin-section-navigation button.is-active .admin-section-navigation-count {
  border-color: rgba(221, 88, 102, .24);
  background: rgba(177, 42, 57, .18);
  color: #ffc0c5;
}

.admin-sidebar-footer {
  display: flex;
  align-items: center;
  gap: 9px;
  margin-top: auto;
  padding: 15px 8px 6px;
  border-top: 1px solid var(--admin-console-border);
}

.admin-sidebar-status {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: #69c48a;
  box-shadow: 0 0 10px rgba(105, 196, 138, .4);
}

.admin-sidebar-footer strong {
  color: #dce1e6;
  font-size: 9px;
}

.admin-sidebar-footer small {
  color: #818a96;
  font-size: 8px;
}

.admin-main-content .admin-page {
  width: 100%;
  max-width: none;
  min-height: calc(100vh - 130px);
  margin: 0;
  padding: 4px 0 24px;
}

.admin-main-content .admin-heading-prominent {
  margin-bottom: 22px;
  padding: 0 0 18px;
  border: 0;
  border-bottom: 1px solid var(--admin-console-border);
  background: none;
  box-shadow: none;
}

.admin-main-content .admin-heading-prominent h1 {
  margin: 5px 0 7px;
  font-size: clamp(28px, 3vw, 38px);
}

.admin-main-content .admin-heading-prominent > div:first-child > p:last-child {
  max-width: 680px;
  margin: 0;
  color: #9ba3ae;
  font-size: 12px;
}

.admin-main-content .admin-section-navigation {
  display: none;
}

.admin-main-content .admin-inventory-overview {
  margin-bottom: 24px;
}

.admin-visit-search {
  position: relative;
  display: flex;
  width: min(100%, 290px);
  align-items: center;
  gap: 8px;
}

.admin-visit-search > .site-icon {
  position: absolute;
  left: 11px;
  width: 16px;
  height: 16px;
  color: var(--admin-console-muted);
  pointer-events: none;
}

.admin-visit-search input {
  width: 100%;
  min-height: 40px;
  padding: 8px 10px 8px 34px;
  border: 1px solid var(--admin-console-border);
  border-radius: 8px;
  background: var(--admin-console-raised);
  color: #f3f4f6;
  font-size: 11px;
}

@media (max-width: 1260px) {
  .admin-console-header {
    grid-template-columns: minmax(145px, .6fr) minmax(240px, 1.2fr) minmax(350px, 1.3fr);
    gap: 12px;
  }

  .admin-console-datetime {
    display: none;
  }

  .admin-main-layout.is-authenticated-admin {
    grid-template-columns: 220px minmax(0, 1fr);
  }
}

@media (max-width: 900px) {
  .site-shell.admin-site-shell .site-header.admin-site-header {
    padding: 10px 16px;
  }

  .admin-console-header {
    grid-template-columns: minmax(125px, .55fr) minmax(220px, 1.3fr) auto;
  }

  .admin-console-tools {
    gap: 8px;
  }

  .admin-account-summary > span:last-child,
  .admin-logout-button {
    display: none;
  }

  .admin-main-layout.is-authenticated-admin {
    grid-template-columns: 190px minmax(0, 1fr);
    gap: 14px;
    padding-right: 16px;
    padding-left: 16px;
  }

  .admin-sidebar {
    padding-right: 7px;
    padding-left: 7px;
  }

  .admin-section-navigation button {
    gap: 7px;
    padding: 0 7px;
  }
}

@media (max-width: 680px) {
  .site-shell.admin-site-shell .site-header.admin-site-header {
    min-height: 120px;
    padding: 10px 14px;
  }

  .admin-console-header {
    grid-template-columns: minmax(0, 1fr) auto;
    gap: 8px 12px;
  }

  .admin-console-title {
    grid-column: 1;
    grid-row: 1;
  }

  .admin-console-title > strong {
    font-size: 14px;
  }

  .admin-console-tools {
    grid-column: 2;
    grid-row: 1;
  }

  .admin-global-search {
    grid-column: 1 / -1;
    grid-row: 2;
  }

  .admin-global-search-form {
    min-height: 42px;
  }

  .admin-global-search-form kbd {
    display: none;
  }

  .admin-main-layout {
    padding-top: 140px;
  }

  .admin-main-layout.is-authenticated-admin {
    display: flex;
    flex-direction: column;
    gap: 15px;
    padding: 138px 14px 32px;
  }

  .admin-sidebar {
    position: static;
    width: 100%;
    min-height: 0;
    padding: 9px;
  }

  .admin-sidebar-heading,
  .admin-sidebar-footer {
    display: none;
  }

  .admin-section-navigation {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 4px;
    margin: 0;
  }

  .admin-section-navigation button {
    min-height: 41px;
    grid-template-columns: 20px minmax(0, 1fr) auto;
    gap: 6px;
    padding: 0 7px;
  }

  .admin-section-navigation-label {
    font-size: 10px;
  }

  .admin-main-content {
    width: 100%;
  }

  .admin-main-content .admin-page {
    min-height: 0;
    padding-top: 0;
  }

  .admin-visit-search {
    width: 100%;
  }
}

